Modules.Kaitun = function(...)

-- ============================================================

-- PRINCE HUB | KAITUN ONLY

-- Visible features kept:

--   1) Auto Kaitun

--   2) Kaitun Sea 2 Auto Join PS

-- Everything else from the old hub was removed from the UI.

-- ============================================================

-- DEFAULT SETTINGS

-- You can override these with getgenv().Config before loading the script.

-- ============================================================

local DefaultConfig = {
	MAIN = {
		LEVEL = 675,
		TWEEN_SPEED = 70,
		STAT_CAP = { STRENGTH = 750, DEFENSE = 1275 },
		PS_CODE = {
			["TPclnqbh0u"] = {"impeldowntesting"},
		},
		AUTO_KAITUN = true,
		AUTO_JOIN_SEA2 = true,
		AUTO_REJOIN = true,
		AUTO_HIDE_UI = true,
		-- Après un crash / Fatal Error / 267, Roblox peut auto-rejoin en serveur public.
		-- Le retour main menu ne doit PAS se faire à chaque lancement normal.
		-- Il se fait seulement si le script a marqué qu'un rejoin/crash vient d'arriver.
		FORCE_PRIVATE_SERVER = true,
		FORCE_MAIN_MENU_ON_REJOIN = true,
		STYLE = { Geppo = true },
		HAKI = { Buso = true },
		ITEM = { ["World Scroll"] = true },
	},
	SETTINGS = {
		OPTIMIZATION = {
			FPS_CAP = 0,
			DISABLE3DRENDER = false,
			LOW_GRAPHICS = true,
		},
	},

}

local function deepMergeConfig(base, override)
	if type(base) ~= "table" or type(override) ~= "table" then
		return base
	end
	for key, value in pairs(override) do
		if type(value) == "table" and type(base[key]) == "table" then
			deepMergeConfig(base[key], value)
		else
			base[key] = value
		end
	end
	return base
end

local userConfig = getgenv().Config

if type(userConfig) == "table" then
	deepMergeConfig(DefaultConfig, userConfig)
	local getConfig = userConfig.GET
	if type(getConfig) == "table" then
		if type(getConfig.STYLE) == "table" then
			DefaultConfig.MAIN.STYLE = DefaultConfig.MAIN.STYLE or {}
			deepMergeConfig(DefaultConfig.MAIN.STYLE, getConfig.STYLE)
		end
		if type(getConfig.HAKI) == "table" then
			DefaultConfig.MAIN.HAKI = DefaultConfig.MAIN.HAKI or {}
			deepMergeConfig(DefaultConfig.MAIN.HAKI, getConfig.HAKI)
		end
		if type(getConfig.ITEM) == "table" then
			DefaultConfig.MAIN.ITEM = DefaultConfig.MAIN.ITEM or {}
			deepMergeConfig(DefaultConfig.MAIN.ITEM, getConfig.ITEM)
		end
	end
end

getgenv().Config = DefaultConfig

-- ============================================================

-- SERVICES / PLACE DETECTION

-- ============================================================

local Players            = game:GetService("Players")

local ReplicatedStorage  = game:GetService("ReplicatedStorage")

local RunService         = game:GetService("RunService")

local TeleportService    = game:GetService("TeleportService")

local VirtualUser        = game:GetService("VirtualUser")

local VirtualInput       = game:GetService("VirtualInputManager")

local CoreGui            = game:GetService("CoreGui")

local UserInputService   = game:GetService("UserInputService")

local StarterGui         = game:GetService("StarterGui")

local Lighting           = game:GetService("Lighting")

local LocalPlayer = Players.LocalPlayer

local LOGIN_PLACE_ID = 1730877806

local LOGIN_PLACE_ID_2 = 6360478118

local SEA2_PLACE_ID = 7465136166

local IS_LOGIN_PLACE = game.PlaceId == LOGIN_PLACE_ID or game.PlaceId == LOGIN_PLACE_ID_2

local IS_SEA2_PLACE = game.PlaceId == SEA2_PLACE_ID

-- ============================================================

-- CONFIG RESOLUTION

-- ============================================================

local function normalizePSValue(value)
	return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

local function normalizePSName(value)
	return normalizePSValue(value):lower()
end

local function resolvePSCode()
	local cfg = DefaultConfig.MAIN
	local psConfig = cfg.PS_CODE
	if not psConfig then return "" end
	if type(psConfig) == "string" then
		local directCode = normalizePSValue(psConfig)
		if directCode == "Public" then return "" end
		return directCode
	end
	if type(psConfig) ~= "table" then
		return ""
	end
	local myName = normalizePSName(LocalPlayer.Name)
	local matches = {}
	for psCode, bots in pairs(psConfig) do
		if type(bots) == "table" then
			for _, entry in ipairs(bots) do
				local userName, weapon
				if type(entry) == "string" then
					userName = entry
				elseif type(entry) == "table" then
					userName = entry.user or entry.username or entry.name
					weapon = entry.weapon
				end
				if normalizePSName(userName) == myName then
					local cleanCode = normalizePSValue(psCode)
					table.insert(matches, {
						code = cleanCode,
						weapon = weapon,
					})
				end
			end
		end
	end
	if #matches == 0 then
		return ""
	end
	-- Si le même username est dans plusieurs PS codes, on évite le hasard de pairs().
	-- Priorité 1: garder le code déjà actif si c'est un des codes trouvés.
	local activeCode = normalizePSValue(getgenv().KaitunSea2Code or "")
	if activeCode ~= "" then
		for _, match in ipairs(matches) do
			if match.code == activeCode then
				if match.weapon then
					DefaultConfig.MAIN.RESOLVED_WEAPON = match.weapon
				end
				if match.code == "Public" then return "" end
				return match.code
			end
		end
	end
	-- Priorité 2: choisir toujours le même code de façon déterministe.
	-- Important: le mieux reste quand même de ne pas mettre un username dans 2 PS codes.
	table.sort(matches, function(a, b)
		return tostring(a.code) < tostring(b.code)
	end)
	local chosen = matches[1]
	DefaultConfig.MAIN.PS_CODE_DUPLICATE_MATCHES = #matches
	if chosen.weapon then
		DefaultConfig.MAIN.RESOLVED_WEAPON = chosen.weapon
	end
	if chosen.code == "Public" then return "" end
	return chosen.code
end

DefaultConfig.MAIN.RESOLVED_PS_CODE = resolvePSCode()

local PS_CODE_SAVE_FILE = "PrinceKaitunSea2PSCode.txt"

local REJOIN_MAIN_MENU_FLAG_FILE = "PrinceKaitunForceMainMenuAfterRejoin.txt"

local function readSavedPSCode()
	local ok, result = pcall(function()
		if isfile and readfile and isfile(PS_CODE_SAVE_FILE) then
			return tostring(readfile(PS_CODE_SAVE_FILE) or "")
		end
		return ""
	end)
	if ok then
		return tostring(result or ""):gsub("^%s+", ""):gsub("%s+$", "")
	end
	return ""
end

local function savePSCode(code)
	code = tostring(code or "")
	getgenv().KaitunSea2Code = code
	DefaultConfig.MAIN.RESOLVED_PS_CODE = code
	pcall(function()
		if writefile then
			writefile(PS_CODE_SAVE_FILE, code)
		end
	end)
end

local REJOIN_FLAG_TTL_SECONDS = 90

local function markMainMenuAfterRejoin()
	-- On ne sauvegarde plus "true".
	-- On sauvegarde un timestamp court, sinon le flag peut rester bloque
	-- et renvoyer main menu meme quand tu rejoins normalement ton PS.
	local now = os.time()
	getgenv().KaitunForceMainMenuAfterRejoinAt = now
	pcall(function()
		if writefile then
			writefile(REJOIN_MAIN_MENU_FLAG_FILE, tostring(now))
		end
	end)
end

local function clearMainMenuAfterRejoin()
	getgenv().KaitunForceMainMenuAfterRejoin = nil
	getgenv().KaitunForceMainMenuAfterRejoinAt = nil
	pcall(function()
		if delfile and isfile and isfile(REJOIN_MAIN_MENU_FLAG_FILE) then
			delfile(REJOIN_MAIN_MENU_FLAG_FILE)
		elseif writefile then
			writefile(REJOIN_MAIN_MENU_FLAG_FILE, "")
		end
	end)
end

local function hasMainMenuAfterRejoinFlag()
	local now = os.time()
	local stamp = tonumber(getgenv().KaitunForceMainMenuAfterRejoinAt)
	if not stamp then
		local ok, value = pcall(function()
			if isfile and readfile and isfile(REJOIN_MAIN_MENU_FLAG_FILE) then
				return tostring(readfile(REJOIN_MAIN_MENU_FLAG_FILE) or "")
			end
			return ""
		end)
		if ok then
			stamp = tonumber(tostring(value or ""):match("%d+"))
		end
	end
	-- Ancien bug: le fichier contenait "true" et restait permanent.
	-- Si ce n'est pas un timestamp valide, on le supprime et on n'agit pas.
	if not stamp then
		clearMainMenuAfterRejoin()
		return false
	end
	-- Flag valide uniquement juste apres Fatal Error / 267 / ErrorPrompt.
	-- Si tu relances le script plus tard ou arrives normalement dans ton PS,
	-- il est ignore et supprime.
	if now - stamp > REJOIN_FLAG_TTL_SECONDS then
		clearMainMenuAfterRejoin()
		return false
	end
	return true
end

local function trimString(value)
	return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

local savedPSCode = readSavedPSCode()

local resolvedConfigPSCode = trimString(DefaultConfig.MAIN.RESOLVED_PS_CODE or "")

local currentSea2Code = trimString(getgenv().KaitunSea2Code or "")

-- IMPORTANT:

-- Avant, la condition `or type(DefaultConfig.MAIN.PS_CODE) == "table"` pouvait

-- forcer KaitunSea2Code = "" quand ton pseudo n'etait pas trouve dans PS_CODE.

-- Maintenant on ne prend le code de config QUE s'il est vraiment resolu.

if resolvedConfigPSCode ~= "" then
	getgenv().KaitunSea2Code = resolvedConfigPSCode
elseif currentSea2Code ~= "" then
	getgenv().KaitunSea2Code = currentSea2Code
elseif savedPSCode ~= "" then
	getgenv().KaitunSea2Code = savedPSCode
else
	getgenv().KaitunSea2Code = ""
end

DefaultConfig.MAIN.RESOLVED_PS_CODE = getgenv().KaitunSea2Code or ""

if DefaultConfig.MAIN.RESOLVED_PS_CODE ~= "" then
	savePSCode(DefaultConfig.MAIN.RESOLVED_PS_CODE)
end

local function getActivePSCode()
	local code = trimString(getgenv().KaitunSea2Code or "")
	if code ~= "" then return code end
	code = trimString(DefaultConfig.MAIN.RESOLVED_PS_CODE or "")
	if code ~= "" then return code end
	return trimString(readSavedPSCode())
end

-- Ne pas utiliser game.PrivateServerId ici.

-- Dans ce jeu / selon le type de serveur, ça peut faire un faux positif

-- et renvoyer au main menu alors que le bot vient d'arriver dans le bon PS.

local function shouldForcePSRoute()
	return DefaultConfig.MAIN.FORCE_PRIVATE_SERVER == true
		and DefaultConfig.MAIN.AUTO_JOIN_SEA2 == true
		and getActivePSCode() ~= ""
end

local function teleportToMainMenuForPS()
	local code = getActivePSCode()
	if code == "" then return false end
	savePSCode(code)
	getgenv().KaitunSea2Code = code
	getgenv().KaitunSea2Pending = true
	pcall(function()
		TeleportService:Teleport(LOGIN_PLACE_ID, LocalPlayer)
	end)
	return true
end

local function shouldForceMainMenuFromCurrentPlace()
	if not shouldForcePSRoute() then return false end
	if DefaultConfig.MAIN.FORCE_MAIN_MENU_ON_REJOIN ~= true then return false end
	if IS_LOGIN_PLACE then return false end
	if not hasMainMenuAfterRejoinFlag() then return false end
	-- Flag one-shot: il sert seulement pour le rejoin juste apres Fatal Error / 267.
	-- On le clear AVANT de partir main menu pour eviter qu'un futur lancement normal
	-- en Sea 1 / Sea 2 prive renvoie encore au main menu.
	clearMainMenuAfterRejoin()
	return true
end

