local function configFlag(sectionName, keyName, default)
	local getSection = DefaultConfig.GET and DefaultConfig.GET[sectionName]
	if type(getSection) == "table" and getSection[keyName] ~= nil then
		return getSection[keyName] == true
	end
	local section = DefaultConfig.MAIN and DefaultConfig.MAIN[sectionName]
	if type(section) ~= "table" or section[keyName] == nil then
		return default == true
	end
	return section[keyName] == true
end

local function makeObjectLowGraphics(obj)
	pcall(function()
		if obj:IsA("BasePart") then
			obj.Material = Enum.Material.SmoothPlastic
			obj.Reflectance = 0
			obj.CastShadow = false
			if obj:IsA("MeshPart") then
				obj.TextureID = ""
				obj.RenderFidelity = Enum.RenderFidelity.Performance
			end
		elseif obj:IsA("Decal") or obj:IsA("Texture") then
			obj.Transparency = 1
		elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam")
			or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") then
			obj.Enabled = false
		elseif obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight") then
			obj.Enabled = false
		elseif obj:IsA("PostEffect") then
			obj.Enabled = false
		elseif obj:IsA("Atmosphere") then
			obj.Density = 0
			obj.Offset = 0
			obj.Haze = 0
			obj.Glare = 0
		elseif obj:IsA("Clouds") then
			obj.Cover = 0
			obj.Density = 0
		end
	end)
end

local function applyLowGraphicsSettings()
	local settings = DefaultConfig.SETTINGS or {}
	local opt = settings.OPTIMIZATION or {}
	if opt.LOW_GRAPHICS ~= true and opt.UGLY_GRAPHICS ~= true then return end
	pcall(function()
		Lighting.GlobalShadows = false
		Lighting.Brightness = 0
		Lighting.EnvironmentDiffuseScale = 0
		Lighting.EnvironmentSpecularScale = 0
		Lighting.FogEnd = 9e9
		Lighting.Technology = Enum.Technology.Compatibility
	end)
	pcall(function()
		local terrain = workspace:FindFirstChild("Terrain")
		if terrain then
			terrain.WaterWaveSize = 0
			terrain.WaterWaveSpeed = 0
			terrain.WaterReflectance = 0
			terrain.WaterTransparency = 1
			terrain.Decoration = false
		end
	end)
	if not H.lowGraphicsConn then
		H.lowGraphicsConn = workspace.DescendantAdded:Connect(function(obj)
			makeObjectLowGraphics(obj)
		end)
	end
	local sweepInterval = H.lowGraphicsInitialSweepDone and (H.LOW_GRAPHICS_SWEEP_INTERVAL or 30) or 0
	if tick() - (H.lastLowGraphicsSweep or 0) >= sweepInterval then
		H.lastLowGraphicsSweep = tick()
		H.lowGraphicsInitialSweepDone = true
		for _, obj in ipairs(workspace:GetDescendants()) do
			makeObjectLowGraphics(obj)
		end
		for _, obj in ipairs(Lighting:GetDescendants()) do
			makeObjectLowGraphics(obj)
		end
	end
end

local function applyOptimizationSettings()
	local settings = DefaultConfig.SETTINGS or {}
	local opt = settings.OPTIMIZATION or {}
	local fpsCap = tonumber(opt.FPS_CAP)
	if fpsCap and fpsCap > 0 then
		pcall(function()
			if type(setfpscap) == "function" then
				setfpscap(fpsCap)
			end
		end)
	end
	pcall(function()
		if RunService.Set3dRenderingEnabled then
			RunService:Set3dRenderingEnabled(opt.DISABLE3DRENDER ~= true)
		end
	end)
	applyLowGraphicsSettings()
end

local function startOptimizationLoop()
	if H.optimizationLoopStarted then return end
	H.optimizationLoopStarted = true
	task.spawn(function()
		while true do
			applyOptimizationSettings()
			task.wait(1)
		end
	end)
end

local function startAutoRejoin()
	if H.autoRejoinStarted or DefaultConfig.MAIN.AUTO_REJOIN ~= true then return end
	H.autoRejoinStarted = true
	local function retryJoin()
		task.wait(2)
		-- Fatal Error / 267 / ErrorPrompt detecte:
		-- On marque le prochain lancement pendant 90 secondes max.
		-- Pas de flag permanent, sinon arrivee normale en PS = faux main menu.
		if shouldForcePSRoute() then
			markMainMenuAfterRejoin()
		end
		TeleportService:Teleport(game.PlaceId, LocalPlayer)
	end
	pcall(function()
		LocalPlayer.OnTeleport:Connect(function(state)
			if state == Enum.TeleportState.Failed then
				retryJoin()
			end
		end)
	end)
	pcall(function()
		local robloxPromptGui = CoreGui:FindFirstChild("RobloxPromptGui")
		local promptOverlay = robloxPromptGui and robloxPromptGui:FindFirstChild("promptOverlay")
		if promptOverlay then
			promptOverlay.ChildAdded:Connect(function(child)
				if child.Name == "ErrorPrompt" then
					retryJoin()
				end
			end)
		end
	end)
end

local function getCharacter()
	local char = LocalPlayer.Character
	if char and char:FindFirstChild("HumanoidRootPart") and char:FindFirstChildOfClass("Humanoid") then
		return char
	end
	local pc = workspace:FindFirstChild("PlayerCharacters")
	local folderChar = pc and pc:FindFirstChild(LocalPlayer.Name)
	if folderChar and folderChar:FindFirstChild("HumanoidRootPart") and folderChar:FindFirstChildOfClass("Humanoid") then
		return folderChar
	end
	return char or folderChar
end

local function getHRP()
	local char = getCharacter()
	return char and char:FindFirstChild("HumanoidRootPart")
end

local function getHumanoid()
	local char = getCharacter()
	return char and char:FindFirstChildOfClass("Humanoid")
end

local function isAlive()
	local hum = getHumanoid()
	local rp = getHRP()
	return hum and hum.Health > 0 and rp ~= nil
end

local function waitUntilAliveStable(timeout)
	timeout = timeout or 8
	local start = tick()
	while tick() - start < timeout do
		local hum = getHumanoid()
		local rp = getHRP()
		if hum and rp and hum.Health > 0 then
			releaseMovementKeys()
			task.wait(0.45)
			return true
		end
		task.wait(0.2)
	end
	return false
end

local function markDeathGraceIfNeeded()
	local hum = getHumanoid()
	if hum and hum.Health <= 0 then
		H.lastDeathTime = tick()
		H.respawnGraceUntil = tick() + H.RESPAWN_WAIT_SECONDS + 3
		H.tpToken = H.tpToken + 1
		releaseMovementKeys()
		return true
	end
	return false
end

local function getStatsRoot()
	return ReplicatedStorage:FindFirstChild("Stats" .. LocalPlayer.Name)
end

local function getLevel()
	local root = getStatsRoot()
	local lv = root and root:FindFirstChild("Stats") and root.Stats:FindFirstChild("Level")
	return lv and lv.Value or 0
end

local function getQuest()
	local root = getStatsRoot()
	local cq = root and root:FindFirstChild("Quest") and root.Quest:FindFirstChild("CurrentQuest")
	return cq and cq.Value or ""
end

local function getInventoryString()
	local root = getStatsRoot()
	local inv = root and root:FindFirstChild("Inventory")
	if not inv then return "" end
	local ok, value = pcall(function()
		return inv.Value
	end)
	if ok and value ~= nil then
		return tostring(value)
	end
	local parts = {}
	for _, obj in ipairs(inv:GetDescendants()) do
		table.insert(parts, tostring(obj.Name))
		local ok2, v = pcall(function()
			return obj.Value
		end)
		if ok2 and v ~= nil then
			table.insert(parts, tostring(v))
		end
	end
	return table.concat(parts, " ")
end

local function hasInventoryItem(itemName)
	itemName = tostring(itemName or "")
	if itemName == "" then return false end
	local root = getStatsRoot()
	local inv = root and root:FindFirstChild("Inventory")
	if inv then
		if inv:FindFirstChild(itemName, true) then
			return true
		end
		for _, obj in ipairs(inv:GetDescendants()) do
			if tostring(obj.Name):lower() == itemName:lower() then
				return true
			end
			local ok, v = pcall(function()
				return obj.Value
			end)
			if ok and tostring(v):lower():find(itemName:lower(), 1, true) then
				return true
			end
		end
	end
	return string.find(getInventoryString():lower(), itemName:lower(), 1, true) ~= nil
end

local function getHakiQuestProgress(fallbackKills)
	local questName = "Road to Armament"
	local currentQuest = getQuest()
	local maxKills = 50
	local questKills = nil
	local debugSource = nil
	local function scanText(t, sourceName)
		if type(t) ~= "string" or t == "" then return end
		-- Match "X / Y" avec espaces optionnels et n'importe quel suffixe
		-- (ex: "1 / 50 Yeti", "1/50", "Beat Yetis: 1/50").
		local a, b = t:match("(%d+)%s*/%s*(%d+)")
		a, b = tonumber(a), tonumber(b)
		if a and b and b > 0 and b <= 100 then
			local newKills = math.clamp(math.floor(a), 0, b)
			if not questKills or newKills > questKills then
				questKills = newKills
				maxKills = math.clamp(math.floor(b), 1, 100)
				debugSource = sourceName or "?"
			end
		end
	end
	local function scanInstanceText(inst)
		if not inst then return end
		if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
			scanText(inst.Text, inst:GetFullName())
		end
	end
	-- 1) Source la plus fiable : le GUI de quete PlayerGui.Quest.Main.Misc.
	--    BusoMastery sert d'ancre, et le texte "11 / 50 Yeti" est scanne
	--    dans le meme bloc Quest.
	pcall(function()
		local pg = LocalPlayer:FindFirstChild("PlayerGui")
		if not pg then return end
		local questGui = pg:FindFirstChild("Quest")
		if not questGui then return end
		local main = questGui:FindFirstChild("Main")
		local misc = main and main:FindFirstChild("Misc")
		local busoMastery = misc and misc:FindFirstChild("BusoMastery")
		if misc then
			for _, d in ipairs(misc:GetDescendants()) do
				scanInstanceText(d)
			end
		end
		if main then
			for _, d in ipairs(main:GetDescendants()) do
				scanInstanceText(d)
			end
		end
		if busoMastery then
			scanInstanceText(busoMastery)
			for _, d in ipairs(busoMastery:GetDescendants()) do
				scanInstanceText(d)
			end
		end
		for _, d in ipairs(questGui:GetDescendants()) do
			scanInstanceText(d)
		end
	end)
	-- 2) Fallback : lire le dossier Quest cÃ´tÃ© ReplicatedStorage si le GUI
	--    n'a rien donnÃ©.
	if not questKills then
		local root = getStatsRoot()
		local questFolder = root and root:FindFirstChild("Quest")
		if questFolder then
			for _, obj in ipairs(questFolder:GetDescendants()) do
				if obj:IsA("IntValue") or obj:IsA("NumberValue") then
					local name = string.lower(obj.Name or "")
					local value = tonumber(obj.Value)
					if value then
						if name:find("progress") or name:find("kill") or name:find("count")
							or name:find("amount") or name:find("current") or name == "value" then
							if value >= 0 and value <= 50 then
								questKills = math.max(questKills or 0, math.floor(value))
								debugSource = "RS:" .. obj:GetFullName()
							end
						elseif name:find("required") or name:find("needed") or name:find("need")
							or name:find("max") or name:find("total") or name:find("goal") then
							if value > 0 and value <= 100 then
								maxKills = math.floor(value)
							end
						end
					end
				elseif obj:IsA("StringValue") then
					scanText(tostring(obj.Value or ""), "RS:" .. obj:GetFullName())
				end
			end
		end
	end
	-- 3) Si on n'a rien trouvÃ© cette fois-ci (PlayerGui pas encore prÃªt
	--    juste aprÃ¨s le respawn par exemple), on garde la derniÃ¨re valeur
	--    connue plutÃ´t que de retomber Ã  0.
	if questKills then
		H.lastQuestProgressKills = questKills
		H.lastQuestProgressMax = maxKills
		H.lastQuestProgressSource = debugSource
	else
		if H.lastQuestProgressKills then
			questKills = H.lastQuestProgressKills
			maxKills = H.lastQuestProgressMax or maxKills
			H.lastQuestProgressSource = (H.lastQuestProgressSource or "?") .. " (cached)"
		else
			H.lastQuestProgressSource = nil
		end
	end
	return questKills or fallbackKills or 0, maxKills
end

local function setNoclip(state)
	H.noclipActive = state == true
	if H.noclipActive and not H.noclipConn then
		local cachedChar = nil
		local cachedParts = {}
		local lastCacheTime = 0
		H.noclipConn = RunService.Stepped:Connect(function()
			if not H.noclipActive then return end
			local char = getCharacter()
			if not char then return end
			local now = tick()
			if char ~= cachedChar or now - lastCacheTime >= 2 then
				cachedChar = char
				cachedParts = {}
				lastCacheTime = now
				for _, obj in ipairs(char:GetDescendants()) do
					if obj:IsA("BasePart") then
						table.insert(cachedParts, obj)
					end
				end
			end
			for _, obj in ipairs(cachedParts) do
				if obj and obj.Parent then obj.CanCollide = false end
			end
			if now - (H.lastNoclipTakeStam or 0) >= 0.30 then
				H.lastNoclipTakeStam = now
				fireTakeStamDash()
			end
		end)
	elseif not H.noclipActive and H.noclipConn then
		H.noclipConn:Disconnect()
		H.noclipConn = nil
	end
end

releaseMovementKeys = function()
	pcall(function()
		for _, key in ipairs({
			Enum.KeyCode.W, Enum.KeyCode.A, Enum.KeyCode.S, Enum.KeyCode.D,
			Enum.KeyCode.Z, Enum.KeyCode.Q,
			Enum.KeyCode.Up, Enum.KeyCode.Down, Enum.KeyCode.Left, Enum.KeyCode.Right,
			}) do
			VirtualInput:SendKeyEvent(false, key, false, game)
		end
	end)
	local hum = getHumanoid()
	local rp = getHRP()
	if hum then
		hum:Move(Vector3.zero, false)
		hum.PlatformStand = false
		hum.Sit = false
		hum.AutoRotate = true
	end
	if rp then
		local bv = rp:FindFirstChild("KT_AirHoldBV")
		if bv then bv:Destroy() end
		local bp = rp:FindFirstChild("KT_AirHoldBP")
		if bp then bp:Destroy() end
		local diveBv = rp:FindFirstChild("KT_WaterDiveBV")
		if diveBv then diveBv:Destroy() end
		rp.AssemblyLinearVelocity = Vector3.zero
		rp.AssemblyAngularVelocity = Vector3.zero
	end
	if hum then
		pcall(function()
			hum:SetStateEnabled(Enum.HumanoidStateType.Swimming, true)
		end)
	end
end

fireTakeStamDash = function()
	local events = ReplicatedStorage:FindFirstChild("Events")
	local takestam = events and events:FindFirstChild("takestam")
	local rp = getHRP()
	if not takestam or not rp then return end
	pcall(function()
		takestam:FireServer(1, "dash", rp.CFrame)
	end)
end

local function fireFaceMouse()
	if H.fishmanEscaping then return end
	local rp = getHRP()
	if rp and isFishmanRegionPosition(rp.Position) then return end
	local events = ReplicatedStorage:FindFirstChild("Events")
	local faceMouse = events and events:FindFirstChild("faceMouse")
	if not faceMouse then return end
	pcall(function()
		faceMouse:FireServer(true)
		faceMouse:FireServer(false)
	end)
end

local function shouldUseTravelFaceMouse(startPos, targetPos, noArc)
	if H.fishmanEscaping then
		return false
	end
	if isFishmanRegionPosition(startPos) then
		return false
	end
	if typeof(startPos) ~= "Vector3" or typeof(targetPos) ~= "Vector3" then
		return false
	end
	local dist = (startPos - targetPos).Magnitude
	local yDiff = math.abs(startPos.Y - targetPos.Y)
	return dist >= 400 or yDiff >= 80 or not noArc
end

local function shouldUseTravelArc(startPos, targetPos, noArc)
	if typeof(startPos) ~= "Vector3" or typeof(targetPos) ~= "Vector3" then
		return false
	end
	local dist = (startPos - targetPos).Magnitude
	if dist < 300 then
		return false
	end
	if not noArc then
		return true
	end
	return dist >= 1000 or startPos.Y < -500 or targetPos.Y < -500
end

local function setWaterDiveAssist(rp, hum, enabled, targetY)
	if not rp then return end
	local diveBv = rp:FindFirstChild("KT_WaterDiveBV")
	if enabled then
		if hum then
			pcall(function()
				hum:SetStateEnabled(Enum.HumanoidStateType.Swimming, false)
			end)
			pcall(function()
				hum:ChangeState(Enum.HumanoidStateType.Freefall)
			end)
		end
		if not diveBv then
			diveBv = Instance.new("BodyVelocity")
			diveBv.Name = "KT_WaterDiveBV"
			diveBv.Parent = rp
		end
		diveBv.MaxForce = Vector3.new(0, 1e9, 0)
		diveBv.P = 1e7
		diveBv.Velocity = Vector3.new(0, -math.clamp(math.abs(rp.Position.Y - (targetY or rp.Position.Y)) + 20, 35, 140), 0)
	else
		if diveBv then diveBv:Destroy() end
		if hum then
			pcall(function()
				hum:SetStateEnabled(Enum.HumanoidStateType.Swimming, true)
			end)
		end
	end
end

local function DoSafeTeleport(targetPos, noArc, allowNoclip)
	if typeof(targetPos) == "CFrame" then targetPos = targetPos.Position end
	if typeof(targetPos) ~= "Vector3" then return end
	local rp = getHRP()
	local hum = getHumanoid()
	if not rp or not hum or hum.Health <= 0 then return end
	H.tpToken = H.tpToken + 1
	local myToken = H.tpToken
	local startPos = rp.Position
	local dist = (startPos - targetPos).Magnitude
	local useTravelFaceMouse = shouldUseTravelFaceMouse(startPos, targetPos, noArc)
	local useTravelArc = shouldUseTravelArc(startPos, targetPos, noArc)
	local holdForwardKey = useTravelFaceMouse or useTravelArc
	if allowNoclip == false then
		setNoclip(false)
	else
		setNoclip(true)
	end
	releaseMovementKeys()
	if holdForwardKey then
		pcall(function()
			VirtualInput:SendKeyEvent(true, Enum.KeyCode.W, false, game)
		end)
	end
	local route = {}
	if useTravelArc then
		local safeAlt = math.max(startPos.Y, targetPos.Y) + 2500
		table.insert(route, Vector3.new(startPos.X, safeAlt, startPos.Z))
		table.insert(route, Vector3.new(targetPos.X, safeAlt, targetPos.Z))
		if targetPos.Y < -500 then
			table.insert(route, Vector3.new(targetPos.X, (safeAlt + targetPos.Y) / 2, targetPos.Z))
		end
	end
	table.insert(route, targetPos)
	local floor = Instance.new("Part")
	floor.Name = "KaitunInvisibleFloor"
	floor.Size = Vector3.new(10, 1, 10)
	floor.Transparency = 1
	floor.Anchored = true
	floor.CanCollide = true
	floor.Parent = workspace
	local moving = true
	task.spawn(function()
		local lastFaceMouse = 0
		while moving and H.tpToken == myToken do
			fireTakeStamDash()
			if useTravelFaceMouse and tick() - lastFaceMouse >= 0.10 then
				lastFaceMouse = tick()
				fireFaceMouse()
			end
			task.wait(0.08)
		end
	end)
	for wpIndex, wp in ipairs(route) do
		if useTravelFaceMouse then
			fireFaceMouse()
		end
		while H.tpToken == myToken do
			rp = getHRP()
			hum = getHumanoid()
			if not rp or not hum or hum.Health <= 0 then break end
			local currentDist = (rp.Position - wp).Magnitude
			local isLastWaypoint = wpIndex == #route
			local reachDistance = isLastWaypoint and 2.5 or 15
			local shouldDiveNow = isLastWaypoint and wp.Y < (rp.Position.Y - 4) and (targetPos.Y < 25 or rp.Position.Y < 25)
			setWaterDiveAssist(rp, hum, shouldDiveNow, wp.Y)
			if currentDist <= reachDistance then
				setWaterDiveAssist(rp, hum, false, wp.Y)
				rp.AssemblyLinearVelocity = Vector3.zero
				rp.AssemblyAngularVelocity = Vector3.zero
				break
			end
			local dt = RunService.Heartbeat:Wait()
			local dir = (wp - rp.Position).Unit
			local step = math.min((H.teleportSpeed or 70) * dt, currentDist)
			if useTravelFaceMouse then
				fireFaceMouse()
			end
			rp.CFrame = (rp.CFrame - rp.Position) + (rp.Position + dir * step)
			rp.AssemblyLinearVelocity = Vector3.zero
			rp.AssemblyAngularVelocity = Vector3.zero
			if floor and floor.Parent then
				floor.CFrame = rp.CFrame * CFrame.new(0, -3.1, 0)
			end
		end
	end
	moving = false
	if floor then floor:Destroy() end
	pcall(function()
		local endRp = getHRP()
		local endHum = getHumanoid()
		if endRp then
			setWaterDiveAssist(endRp, endHum, false, targetPos.Y)
		end
	end)
	releaseMovementKeys()
end

local function DoHakiSafeTeleport(targetPos, finalHoverY)
	if typeof(targetPos) == "CFrame" then targetPos = targetPos.Position end
	if typeof(targetPos) ~= "Vector3" then return end
	if tick() < (H.respawnGraceUntil or 0) then
		waitUntilAliveStable(H.RESPAWN_WAIT_SECONDS + 5)
		task.wait(0.5)
	end
	local rp = getHRP()
	local hum = getHumanoid()
	if not rp or not hum or hum.Health <= 0 then return end
	if targetPos.Y < H.YETI_MIN_SAFE_Y then
		targetPos = Vector3.new(targetPos.X, H.YETI_MIN_SAFE_Y + H.YETI_HOVER_HEIGHT, targetPos.Z)
	end
	if finalHoverY and finalHoverY < H.YETI_MIN_SAFE_Y then
		finalHoverY = H.YETI_MIN_SAFE_Y + H.YETI_HOVER_HEIGHT
	end
	setNoclip(true)
	releaseMovementKeys()
	local startPos = rp.Position
	local finalPos = finalHoverY and Vector3.new(targetPos.X, finalHoverY, targetPos.Z) or targetPos
	local flatDist = Vector3.new(targetPos.X - startPos.X, 0, targetPos.Z - startPos.Z).Magnitude
	local yDist = math.abs((finalHoverY or targetPos.Y) - startPos.Y)
	local route = {}
	if flatDist <= 120 and yDist <= 90 then
		table.insert(route, finalPos)
	else
		local safeY = math.max(startPos.Y, targetPos.Y, finalHoverY or targetPos.Y) + 80
		if safeY < 140 then safeY = 140 end
		table.insert(route, Vector3.new(startPos.X, safeY, startPos.Z))
		table.insert(route, Vector3.new(targetPos.X, safeY, targetPos.Z))
		table.insert(route, finalPos)
	end
	for _, wp in ipairs(route) do
		if not getgenv().KaitunFarm then break end
		DoSafeTeleport(wp, true, true)
		task.wait(0.08)
	end
end

