-- AUTO JOIN PS KAITUN SEA 2

-- ============================================================

local autoJoinRunning = false

local codeSent = false

local function joinOnPrivateServer(targetCode, seaChoice)
	local playerGui = LocalPlayer:WaitForChild("PlayerGui")
	local chooseTypeRemote = playerGui:FindFirstChild("chooseType")
		and playerGui.chooseType:FindFirstChild("Frame")
		and playerGui.chooseType.Frame:FindFirstChild("RemoteEvent")
	local confirmRemote = playerGui:FindFirstChild("ConfirmationPrompt")
		and playerGui.ConfirmationPrompt:FindFirstChild("RemoteEvent")
	if confirmRemote then
		confirmRemote:FireServer(seaChoice)
		notify("Kaitun Sea 2", seaChoice .. " selected.", 4)
		return "done"
	elseif chooseTypeRemote then
		chooseTypeRemote:FireServer(true)
		notify("Kaitun Sea 2", "Regular clicked. Waiting confirmation...", 3)
		return "waiting_confirm"
	else
		if not codeSent then
			codeSent = true
			task.spawn(function()
				pcall(function()
					ReplicatedStorage:WaitForChild("Events"):WaitForChild("reserved"):InvokeServer(targetCode)
				end)
			end)
			notify("Kaitun Sea 2", "PS code sent. Waiting menu...", 3)
		end
		return "waiting_menu"
	end
end

local function startAutoJoinSea2(code)
	code = trimString(code or getActivePSCode())
	if code == "" then
		notify("Kaitun Sea 2", "No PS code set.", 5)
		return false
	end
	savePSCode(code)
	getgenv().KaitunSea2Code = code
	getgenv().KaitunSea2Pending = true
	if not IS_LOGIN_PLACE then
		notify("Kaitun Sea 2", "Not in main menu. Teleporting main menu first...", 6)
		teleportToMainMenuForPS()
		return true
	end
	autoJoinRunning = true
	codeSent = false
	task.spawn(function()
		while autoJoinRunning do
			if IS_LOGIN_PLACE then
				local result = joinOnPrivateServer(code, "Second Sea")
				if result == "done" then
					autoJoinRunning = false
					codeSent = false
					break
				end
				task.wait(2)
			elseif IS_SEA2_PLACE then
				autoJoinRunning = false
				getgenv().KaitunSea2Pending = false
				if H.startSea2Farm then
					H.startSea2Farm()
				end
				break
			else
				notify("Kaitun Sea 2", "Teleporting main menu first...", 4)
				pcall(function()
					TeleportService:Teleport(LOGIN_PLACE_ID, LocalPlayer)
				end)
				task.wait(5)
			end
		end
	end)
	return true
end

local function stopAutoJoinSea2()
	autoJoinRunning = false
	codeSent = false
	getgenv().KaitunSea2Pending = false
end

