-- UTILITY LOOPS: AUTO ADS + AUTO STATS

-- ============================================================

local function startUtilityLoops()
	if H.utilityLoopsStarted then return end
	H.utilityLoopsStarted = true
	task.spawn(function()
		local adEvent = ReplicatedStorage:WaitForChild("Events"):WaitForChild("ADShop")
		while true do
			if H.autoAdsEnabled then
				pcall(function()
					adEvent:FireServer(3457788725, "536248645108658")
				end)
			end
			task.wait(10)
		end
	end)
	task.spawn(function()
		local statsEvent = ReplicatedStorage:WaitForChild("Events"):WaitForChild("stats")
		while true do
			if H.autoStatsEnabled then
				local root = getStatsRoot()
				local statsFolder = root and root:FindFirstChild("Stats")
				local statPoints = statsFolder and statsFolder:FindFirstChild("SkillPoints")
				if statPoints and statPoints.Value > 0 then
					local pts = statPoints.Value
					local strengthStat = statsFolder and statsFolder:FindFirstChild("Strength")
					local defenseStat = statsFolder and statsFolder:FindFirstChild("Defense")
					local currentStrength = strengthStat and strengthStat.Value or 0
					local currentDefense = defenseStat and defenseStat.Value or 0
					local strCap = (DefaultConfig.MAIN.STAT_CAP and DefaultConfig.MAIN.STAT_CAP.STRENGTH) or 700
					local defCap = (DefaultConfig.MAIN.STAT_CAP and DefaultConfig.MAIN.STAT_CAP.DEFENSE) or 1275
					local statPattern = { "Strength", "Strength", "Defense" }
					for _ = 1, pts do
						if not H.autoStatsEnabled then break end
						local wantedStat = statPattern[H.autoStatsPatternIndex or 1]
						H.autoStatsPatternIndex = (H.autoStatsPatternIndex or 1) % #statPattern + 1
						if wantedStat == "Strength" and currentStrength < strCap then
							pcall(function() statsEvent:FireServer("Strength", nil, 1) end)
							currentStrength = currentStrength + 1
						elseif wantedStat == "Defense" and currentDefense < defCap then
							pcall(function() statsEvent:FireServer("Defense", nil, 1) end)
							currentDefense = currentDefense + 1
						elseif currentStrength < strCap then
							pcall(function() statsEvent:FireServer("Strength", nil, 1) end)
							currentStrength = currentStrength + 1
						elseif currentDefense < defCap then
							pcall(function() statsEvent:FireServer("Defense", nil, 1) end)
							currentDefense = currentDefense + 1
						else
							break
						end
						task.wait(0.03)
					end
				end
			end
			task.wait(1.20)
		end
	end)
end

-- ============================================================

-- COMBAT HELPERS

-- ============================================================

local combatRegister = ReplicatedStorage:WaitForChild("Events"):WaitForChild("CombatRegister")

local questEvent = ReplicatedStorage:WaitForChild("Events"):WaitForChild("Quest")

local combatAnimations = ReplicatedStorage:WaitForChild("CombatAnimations"):WaitForChild("Melee")

local CombatAnims = {
	[1] = combatAnimations.Punch1,
	[2] = combatAnimations.Punch2,
	[3] = combatAnimations.Punch3,
	[4] = combatAnimations.GroundPunch4,
	[5] = combatAnimations.GroundPunch5,

}

local function equipMelee()
	local backpack = LocalPlayer:FindFirstChild("Backpack")
	local char = getCharacter()
	if not backpack or not char then return false end
	if char:FindFirstChild("Melee") then return true end
	local melee = backpack:FindFirstChild("Melee")
	if not melee then return false end
	local hum = char:FindFirstChildOfClass("Humanoid")
	if hum then
		pcall(function() hum:EquipTool(melee) end)
	else
		melee.Parent = char
	end
	task.wait(0.2)
	return char:FindFirstChild("Melee") ~= nil
end

local function getNPCID(npc)
	if not npc then return nil end
	local v = npc:FindFirstChild("NPCID")
	if v then return v.Value end
	local cfg = npc:FindFirstChild("Configuration")
	if cfg then
		local cv = cfg:FindFirstChild("NPCID")
		if cv then return cv.Value end
	end
	return npc:GetAttribute("NPCID")
end

local function getAllNPCs(targetName)
	local result = {}
	local function scan(folderName)
		local folder = workspace:FindFirstChild(folderName)
		if not folder then return end
		for _, npc in ipairs(folder:GetChildren()) do
			if npc:IsA("Model") and string.find(string.lower(npc.Name), string.lower(targetName), 1, true) then
				local hum = npc:FindFirstChild("Humanoid")
				local hrp = npc:FindFirstChild("HumanoidRootPart")
				if hum and hum.Health > 0 and hrp then
					table.insert(result, { npc = npc, hrp = hrp })
				end
			end
		end
	end
	scan("NPCs")
	scan("Enemies")
	return result
end

local function getClosestNPC(targetName)
	local rp = getHRP()
	if not rp then return nil end
	local closest, bestDist = nil, math.huge
	for _, d in ipairs(getAllNPCs(targetName)) do
		local dist = (rp.Position - d.hrp.Position).Magnitude
		if dist < bestDist then
			closest = d.npc
			bestDist = dist
		end
	end
	return closest
end

local function collectNPCPacket(targetName, centerPos, radius)
	local hrpList = {}
	local npcIDs = {}
	radius = radius or 24
	for _, d in ipairs(getAllNPCs(targetName)) do
		if d.hrp and (d.hrp.Position - centerPos).Magnitude <= radius then
			table.insert(hrpList, d.hrp)
			local id = getNPCID(d.npc)
			if id then table.insert(npcIDs, id) end
		end
	end
	return hrpList, npcIDs
end

local function getClosestNPCToPosition(targetName, centerPos, radius)
	local closest, bestDist = nil, math.huge
	radius = radius or 30
	for _, d in ipairs(getAllNPCs(targetName)) do
		local hum = d.npc and d.npc:FindFirstChild("Humanoid")
		if d.hrp and hum and hum.Health > 0 then
			local dist = (d.hrp.Position - centerPos).Magnitude
			if dist <= radius and dist < bestDist then
				closest = d.npc
				bestDist = dist
			end
		end
	end
	return closest
end

local AIR_HOLD_BV_NAME = "KT_AirHoldBV"

local AIR_HOLD_BP_NAME = "KT_AirHoldBP"

local function enableAirHold(rp, targetPos)
	if not rp then return end
	targetPos = targetPos or rp.Position
	local bv = rp:FindFirstChild(AIR_HOLD_BV_NAME)
	if not bv then
		bv = Instance.new("BodyVelocity")
		bv.Name = AIR_HOLD_BV_NAME
		bv.Parent = rp
	end
	bv.MaxForce = Vector3.new(1e9, 1e9, 1e9)
	bv.P = 1e7
	bv.Velocity = Vector3.zero
	local bp = rp:FindFirstChild(AIR_HOLD_BP_NAME)
	if not bp then
		bp = Instance.new("BodyPosition")
		bp.Name = AIR_HOLD_BP_NAME
		bp.Parent = rp
	end
	bp.MaxForce = Vector3.new(1e9, 1e9, 1e9)
	bp.P = 1e7
	bp.D = 1000
	bp.Position = targetPos
end

local function disableAirHold()
	local rp = getHRP()
	if not rp then return end
	local bv = rp:FindFirstChild(AIR_HOLD_BV_NAME)
	if bv then bv:Destroy() end
	local bp = rp:FindFirstChild(AIR_HOLD_BP_NAME)
	if bp then bp:Destroy() end
end

local function hardLockRoot(rp, hum, cf)
	if not rp or not hum then return end
	enableAirHold(rp, cf.Position)
	hum.PlatformStand = false
	hum.Sit = false
	hum.AutoRotate = false
	hum:ChangeState(Enum.HumanoidStateType.Freefall)
	rp.CFrame = cf
	rp.AssemblyLinearVelocity = Vector3.zero
	rp.AssemblyAngularVelocity = Vector3.zero
	rp.Velocity = Vector3.zero
end

local function lockAbovePosition(pos, duration)
	if typeof(pos) ~= "Vector3" then return end
	local untilTime = tick() + (duration or 0.25)
	while tick() < untilTime do
		local rp = getHRP()
		local hum = getHumanoid()
		if not rp or not hum or hum.Health <= 0 then break end
		hardLockRoot(rp, hum, CFrame.new(pos))
		RunService.Heartbeat:Wait()
	end
end

-- Calcule la CFrame de combat pour les yetis : on reste centre au-dessus

-- du yeti Ã  hauteur fixedY, sans rotation couchÃ©e.

local function getYetiCombatCFrame(yetiHrp, fixedY, currentRp)
	if not yetiHrp then return nil end
	local dist = tonumber(H.YETI_HIT_DISTANCE) or 8.5
	local hoverY = fixedY or (yetiHrp.Position.Y + (tonumber(H.YETI_HOVER_HEIGHT) or 8.3))
	local pos
	if dist <= 0 then
		pos = Vector3.new(yetiHrp.Position.X, hoverY, yetiHrp.Position.Z)
	else
		local away
		if currentRp then
			away = Vector3.new(
				currentRp.Position.X - yetiHrp.Position.X,
				0,
				currentRp.Position.Z - yetiHrp.Position.Z
			)
		end
		if not away or away.Magnitude <= 0.05 then
			local a = math.rad(tonumber(H.YETI_HIT_ROTATION_Y) or 0)
			away = Vector3.new(math.sin(a), 0, math.cos(a))
		else
			away = away.Unit
		end
		pos = Vector3.new(
			yetiHrp.Position.X + away.X * dist,
			hoverY,
			yetiHrp.Position.Z + away.Z * dist
		)
	end
	local rotX = math.rad(tonumber(H.YETI_HIT_ROTATION_X) or 0)
	local rotY = math.rad(tonumber(H.YETI_HIT_ROTATION_Y) or 0)
	local rotZ = math.rad(tonumber(H.YETI_HIT_ROTATION_Z) or 0)
	return CFrame.new(pos) * CFrame.Angles(rotX, rotY, rotZ)
end

local function lockAboveNPC(npc, hoverHeight, duration, fixedY)
	hoverHeight = hoverHeight or 8.6
	local untilTime = tick() + (duration or 0.25)
	local isYeti = npc and npc.Name == "Yeti"
	while tick() < untilTime do
		local rp = getHRP()
		local humSelf = getHumanoid()
		local hrp = npc and npc:FindFirstChild("HumanoidRootPart")
		local hum = npc and npc:FindFirstChild("Humanoid")
		if not rp or not humSelf or humSelf.Health <= 0 or not hrp or not hum or hum.Health <= 0 then
			break
		end
		local y = fixedY or (hrp.Position.Y + hoverHeight)
		local cf
		if isYeti then
			cf = getYetiCombatCFrame(hrp, y, rp) or CFrame.new(hrp.Position.X, y, hrp.Position.Z)
		else
			cf = CFrame.new(hrp.Position.X, y, hrp.Position.Z)
		end
		hardLockRoot(rp, humSelf, cf)
		RunService.Heartbeat:Wait()
	end
end

local function doDamageCombo(targetName, centerPos, lockPos, radius)
	local rp = getHRP()
	if not rp then return end
	equipMelee()
	local hoverHeight = 8.6
	if lockPos and typeof(lockPos) == "Vector3" then
		hoverHeight = math.max(2, lockPos.Y - centerPos.Y)
	end
	for combo = 1, 5 do
		if not getgenv().KaitunFarm and not getgenv().Sea2Farm then break end
		local followNpc = getClosestNPCToPosition(targetName, centerPos, radius or 30)
		local fixedCombatY = lockPos and lockPos.Y or (centerPos.Y + hoverHeight)
		local clusterCenterPos = centerPos
		if followNpc then
			lockAboveNPC(followNpc, hoverHeight, 0.08, fixedCombatY)
		elseif lockPos then
			lockAbovePosition(lockPos, 0.08)
		end
		pcall(function()
			local current = getHRP()
			local followHrp = followNpc and followNpc:FindFirstChild("HumanoidRootPart")
			local followHum = followNpc and followNpc:FindFirstChild("Humanoid")
			local clusterRadius = math.max(radius or 24, 36)
			if current and followHrp and followHum and followHum.Health > 0 then
				clusterCenterPos = followHrp.Position
				current.CFrame = CFrame.new(followHrp.Position.X, fixedCombatY, followHrp.Position.Z)
				current.AssemblyLinearVelocity = Vector3.zero
				current.AssemblyAngularVelocity = Vector3.zero
			elseif current and lockPos then
				current.CFrame = CFrame.new(lockPos)
				current.AssemblyLinearVelocity = Vector3.zero
				current.AssemblyAngularVelocity = Vector3.zero
			end
			local hrpList, npcIDs = collectNPCPacket(targetName, clusterCenterPos, clusterRadius)
			if #hrpList == 0 and followHrp then
				hrpList = { followHrp }
				local id = getNPCID(followNpc)
				if id then npcIDs = { id } end
			end
			if #hrpList == 0 then return end
			combatRegister:InvokeServer({
				[1] = "swingsfx", [2] = "Melee", [3] = combo,
				[4] = "Ground", [5] = false, [6] = CombatAnims[combo],
				[7] = 2, [8] = 1.5,
			})
			current = getHRP()
			followHrp = followNpc and followNpc:FindFirstChild("HumanoidRootPart")
			followHum = followNpc and followNpc:FindFirstChild("Humanoid")
			if current and followHrp and followHum and followHum.Health > 0 then
				clusterCenterPos = followHrp.Position
				current.CFrame = CFrame.new(followHrp.Position.X, fixedCombatY, followHrp.Position.Z)
				current.AssemblyLinearVelocity = Vector3.zero
				current.AssemblyAngularVelocity = Vector3.zero
			elseif current and lockPos then
				current.CFrame = CFrame.new(lockPos)
				current.AssemblyLinearVelocity = Vector3.zero
				current.AssemblyAngularVelocity = Vector3.zero
			end
			local packet = {
				[1] = {
					[1] = "damage", [2] = hrpList, [3] = "Melee",
					[4] = { combo, "Ground", "Melee" }, [5] = true,
					[6] = current and current.CFrame or CFrame.new(lockPos or centerPos),
					aircombo = "Ground",
				}
			}
			if #npcIDs > 0 then packet[1].NPCIDs = npcIDs end
			combatRegister:InvokeServer(unpack(packet))
		end)
		if followNpc then
			lockAboveNPC(followNpc, hoverHeight, 0.05, fixedCombatY)
		elseif lockPos then
			lockAbovePosition(lockPos, 0.05)
		else
			task.wait(0.21)
		end
	end
	local finalNpc = getClosestNPCToPosition(targetName, centerPos, radius or 30)
	if finalNpc then
		local fixedFinalY = lockPos and lockPos.Y or (centerPos.Y + hoverHeight)
		lockAboveNPC(finalNpc, hoverHeight, 1, fixedFinalY)
	elseif lockPos then
		lockAbovePosition(lockPos, 1)
	else
		task.wait(1)
	end
end

local function hitSingleNPC(npc, hoverHeight)
	local hrp = npc and npc:FindFirstChild("HumanoidRootPart")
	local rp = getHRP()
	if not hrp or not rp then return end
	hoverHeight = hoverHeight or 8.6
	local fixedCombatY = hrp.Position.Y + hoverHeight
	lockAboveNPC(npc, hoverHeight, 0.12, fixedCombatY)
	local id = getNPCID(npc)
	pcall(function()
		local current = getHRP()
		local liveHrp = npc and npc:FindFirstChild("HumanoidRootPart")
		local liveHum = npc and npc:FindFirstChild("Humanoid")
		local packetCenter = liveHrp and liveHrp.Position or hrp.Position
		if current and liveHrp and liveHum and liveHum.Health > 0 then
			current.CFrame = CFrame.new(liveHrp.Position.X, fixedCombatY, liveHrp.Position.Z)
			current.AssemblyLinearVelocity = Vector3.zero
			current.AssemblyAngularVelocity = Vector3.zero
		end
		combatRegister:InvokeServer({
			[1] = "swingsfx", [2] = "Melee", [3] = 1,
			[4] = "Ground", [5] = false, [6] = CombatAnims[1],
			[7] = 2, [8] = 1.5,
		})
		current = getHRP()
		liveHrp = npc and npc:FindFirstChild("HumanoidRootPart")
		liveHum = npc and npc:FindFirstChild("Humanoid")
		packetCenter = liveHrp and liveHrp.Position or packetCenter
		if current and liveHrp and liveHum and liveHum.Health > 0 then
			current.CFrame = CFrame.new(liveHrp.Position.X, fixedCombatY, liveHrp.Position.Z)
			current.AssemblyLinearVelocity = Vector3.zero
			current.AssemblyAngularVelocity = Vector3.zero
		end
		local hrpList, npcIDs = collectNPCPacket(npc.Name, packetCenter, 22)
		if #hrpList == 0 then
			hrpList = { liveHrp or hrp }
			if id then npcIDs = { id } end
		end
		local packet = {
			[1] = {
				[1] = "damage", [2] = hrpList, [3] = "Melee",
				[4] = { 1, "Ground", "Melee" }, [5] = true,
				[6] = current and current.CFrame or CFrame.new(hrp.Position.X, fixedCombatY, hrp.Position.Z),
				aircombo = "Ground",
			}
		}
		if #npcIDs > 0 then packet[1].NPCIDs = npcIDs end
		combatRegister:InvokeServer(unpack(packet))
	end)
	lockAboveNPC(npc, hoverHeight, 0.45, fixedCombatY)
end

