-- FISHMAN ROUTES

-- ============================================================

local FISHMAN_CAVE_PATH = {
	Vector3.new(8004.085, -2153.832, -17015.412),
	Vector3.new(8003.483, -2153.832, -17143.662),
	Vector3.new(7860.256, -2153.832, -17159.465),
	Vector3.new(7817.588, -2176.832, -17167.414),
	Vector3.new(7778.929, -2176.832, -17228.219),
	Vector3.new(7764.174, -2176.855, -17280.283),
	Vector3.new(7747.894, -2176.832, -17314.391),

}

local FISHMAN_ESCAPE_PATH = {
	Vector3.new(8015.373, -2153.832, -17116.010),
	Vector3.new(8211.618, -2141.832, -17101.418),
	Vector3.new(8229.126, -2141.832, -17159.701),
	Vector3.new(8525.697, -2140.832, -17158.080),
	Vector3.new(8544.997, -2138.832, -17090.734),
	Vector3.new(8576.332, -2138.832, -17089.451),

}

local function isOnFishmanIsland()
	local rp = getHRP()
	if not rp then return false end
	return isFishmanRegionPosition(rp.Position)
end

local function isInFishmanCave()
	local rp = getHRP()
	if not rp then return false end
	return isFishmanRegionPosition(rp.Position)
end

local function getFishmanExitPart()
	local area = workspace:FindFirstChild("AreaTeleporters")
	local firstSea = area and area:FindFirstChild("FirstSea")
	local fishman = firstSea and firstSea:FindFirstChild("Fishman")
	return fishman and fishman:FindFirstChild("Part2")
end

local function tweenIntoPart(part)
	if not part or not part:IsA("BasePart") then return false end
	local targetPos = part.Position
	local started = tick()
	setNoclip(true)
	releaseMovementKeys()
	while tick() - started < 4 do
		local rp = getHRP()
		local hum = getHumanoid()
		if not rp or not hum or hum.Health <= 0 then return false end
		local delta = targetPos - rp.Position
		local dist = delta.Magnitude
		if dist <= 1.2 then
			rp.AssemblyLinearVelocity = Vector3.zero
			rp.AssemblyAngularVelocity = Vector3.zero
			return true
		end
		local dt = RunService.Heartbeat:Wait()
		local step = math.min((H.teleportSpeed or 70) * dt, dist)
		rp.CFrame = CFrame.new(rp.Position + delta.Unit * step)
		rp.AssemblyLinearVelocity = Vector3.zero
		rp.AssemblyAngularVelocity = Vector3.zero
	end
	return false
end

local function DoFishmanEscapeTeleport(targetPos)
	if typeof(targetPos) == "CFrame" then targetPos = targetPos.Position end
	if typeof(targetPos) ~= "Vector3" then return false end
	local started = tick()
	setNoclip(true)
	releaseMovementKeys()
	while tick() - started < 10 do
		local rp = getHRP()
		local hum = getHumanoid()
		if not rp or not hum or hum.Health <= 0 then return false end
		local delta = targetPos - rp.Position
		local dist = delta.Magnitude
		if dist <= 2.5 then
			rp.CFrame = CFrame.new(targetPos)
			rp.AssemblyLinearVelocity = Vector3.zero
			rp.AssemblyAngularVelocity = Vector3.zero
			return true
		end
		local dt = RunService.Heartbeat:Wait()
		local step = math.min((H.teleportSpeed or 70) * dt, dist, 5)
		local dir = delta.Unit
		rp.CFrame = CFrame.new(rp.Position + dir * step)
		rp.AssemblyLinearVelocity = Vector3.zero
		rp.AssemblyAngularVelocity = Vector3.zero
	end
	return false
end

local function fishmanEscape()
	if not isInFishmanCave() and not isOnFishmanIsland() then return false end
	notify("Kaitun", "Leaving Fishman Island...", 4)
	setNoclip(true)
	H.fishmanEscaping = true
	local escapeWaitPos = Vector3.new(8588.937, -2138.832, -17086.459)
	local ok = pcall(function()
		for _, wp in ipairs(FISHMAN_ESCAPE_PATH) do
			if not getgenv().KaitunFarm and not getgenv().Sea2Farm then break end
			DoFishmanEscapeTeleport(wp)
			task.wait(0.21)
		end
		local exitPart = getFishmanExitPart()
		if exitPart then
			notify("Kaitun", "Entering Fishman Part2 teleporter...", 4)
			DoFishmanEscapeTeleport(exitPart.Position)
			tweenIntoPart(exitPart)
		else
			DoFishmanEscapeTeleport(escapeWaitPos)
		end
	end)
	releaseMovementKeys()
	H.fishmanEscaping = false
	notify("Kaitun", "Fishman teleporter reached. Waiting 4s before Geppo...", 4)
	task.wait(4)
	return ok
end

local function ensureEscapedFishman(context)
	if not isAlive() then
		waitUntilAliveStable(8)
	end
	for _ = 1, 10 do
		local rp = getHRP()
		if rp then break end
		task.wait(0.1)
	end
	if not isInFishmanCave() and not isOnFishmanIsland() then
		return false
	end
	notify("Kaitun", tostring(context or "Fishman Cave") .. ": escaping Fishman by waypoints first...", 5)
	H.tpToken = H.tpToken + 1
	setNoclip(true)
	releaseMovementKeys()
	local escaped = fishmanEscape()
	waitUntilAliveStable(5)
	releaseMovementKeys()
	return escaped
end

