-- KAITUN REQUIREMENT CHECKS

-- ============================================================

local function hasSkyWalk()
	local root = getStatsRoot()
	local sk = root and root:FindFirstChild("Skills") and root.Skills:FindFirstChild("skyWalk")
	return sk and sk.Value == true
end

local function hasHaki()
	local root = getStatsRoot()
	local bm = root and root:FindFirstChild("Stats") and root.Stats:FindFirstChild("BusoMastery")
	return bm and bm.Value > 0
end

local function hasWorldScroll()
	if hasInventoryItem("World Scroll") then
		return true
	end
	local ok, found = pcall(function()
		local pg = LocalPlayer:FindFirstChild("PlayerGui")
		local inv = pg and pg:FindFirstChild("Inventory")
		local main = inv and inv:FindFirstChild("Main")
		if not main then return false end
		local wasOpen = main.Visible
		main.Visible = true
		task.wait(0.2)
		local list = main:FindFirstChild("Inventory") and main.Inventory:FindFirstChild("List")
		local result = false
		if list then
			for _, child in ipairs(list:GetDescendants()) do
				if child.Name == "World Scroll" then
					result = true
					break
				end
			end
		end
		main.Visible = wasOpen
		return result
	end)
	return ok and found == true
end

-- ============================================================

-- PHASE 1: FISHMAN FARM TO 425

-- ============================================================

local function cancelQuestIfDifferent(wantedQuest)
	wantedQuest = tostring(wantedQuest or "")
	local current = getQuest()
	if current == "" or current == wantedQuest then
		return false
	end
	notify("Quest", "Cancel old quest: " .. tostring(current) .. " -> " .. tostring(wantedQuest), 4)
	pcall(function()
		questEvent:InvokeServer({ [1] = "quit" })
	end)
	pcall(function()
		local args = { { "quit" } }
		questEvent:InvokeServer(unpack(args))
	end)
	task.wait(0.35)
	if getQuest() ~= "" and getQuest() ~= wantedQuest then
		local playerGui = LocalPlayer:FindFirstChild("PlayerGui")
		local quitBtn = playerGui
			and playerGui:FindFirstChild("Quest")
			and playerGui.Quest:FindFirstChild("Main")
			and playerGui.Quest.Main:FindFirstChild("Misc")
			and playerGui.Quest.Main.Misc:FindFirstChild("Quit")
		if quitBtn then
			pcall(function() quitBtn:Activate() end)
		end
	end
	task.wait(0.65)
	return true
end

local function takeQuest(questName, questPos, safeNoNoclip)
	if not questName or questName == "" then return end
	releaseMovementKeys()
	cancelQuestIfDifferent(questName)
	if getQuest() == questName then
		return
	end
	DoSafeTeleport(questPos, safeNoNoclip == true, safeNoNoclip ~= true)
	task.wait(1)
	cancelQuestIfDifferent(questName)
	pcall(function()
		questEvent:InvokeServer({ [1] = "takequest", [2] = questName })
	end)
	task.wait(1)
end

-- ============================================================

-- PHASE 1: FISHMAN FARM TO 425

-- FIX: le perso se pose UNE FOIS sur le lockPos (centre cave + hoverHeight)

-- et n'en bouge plus. doDamageCombo frappe tout dans le rayon sans TP NPC par NPC.

-- ============================================================

local function phase1FishmanFarm()
	notify("Kaitun", "Phase 1: Fishman farm", 5)
	getgenv().KaitunFarm = true
	H.autoAdsEnabled = true
	H.autoStatsEnabled = true
	setNoclip(true)
	H.teleportSpeed = DefaultConfig.MAIN.TWEEN_SPEED or 70
	local targetName    = "Fishman Karate User"
	local questName     = "Help becky"
	local questMinLevel = 190
	local questPos      = Vector3.new(7731.026, -2175.832, -17222.637)
	local center        = Vector3.new(7736.441, -2176.832, -17308.871)
	local hoverHeight   = 8.4
	local arrivedAtCave = false
	-- Position de combat fixe : au-dessus du centre de la cave, le perso n'en bouge plus
	local lockPos = Vector3.new(center.X, center.Y + hoverHeight, center.Z)
	while getgenv().KaitunFarm do
		if not isAlive() then task.wait(0.5) continue end
		local level    = getLevel()
		local levelCap = DefaultConfig.MAIN.LEVEL or 675
		if level >= 425 then
			notify("Kaitun", "Level 425 reached. Leaving Fishman phase.", 5)
			break
		end
		if level >= levelCap then
			notify("Kaitun", "Configured level reached.", 5)
			break
		end
		equipMelee()
		local rp = getHRP()
		if not rp then task.wait(0.5) continue end
		-- Aller a la cave une seule fois via les waypoints
		if not arrivedAtCave then
			if (rp.Position - center).Magnitude > 120 then
				notify("Kaitun", "Going to Fishman cave by waypoints...", 4)
				for _, wp in ipairs(FISHMAN_CAVE_PATH) do
					if not getgenv().KaitunFarm then break end
					DoSafeTeleport(wp, true)
					task.wait(0.21)
				end
			end
			-- Se poser sur le lockPos central et y rester
			DoSafeTeleport(lockPos, true)
			task.wait(0.3)
			arrivedAtCave = true
		end
		-- Si le perso s'est eloigne du lockPos (mort/respawn/knockback), le ramener
		rp = getHRP()
		if not rp then task.wait(0.5) continue end
		if (rp.Position - lockPos).Magnitude > 20 then
			arrivedAtCave = false
			continue
		end
		-- Prendre la quete si besoin (revenir au lockPos apres)
		if level >= questMinLevel and getQuest() ~= questName then
			takeQuest(questName, questPos)
			DoSafeTeleport(lockPos, true)
			task.wait(0.5)
			continue
		end
		local npcs = getAllNPCs(targetName)
		if #npcs == 0 then
			-- Pas de NPC, rester ancre sur le lockPos en attendant le respawn
			enableAirHold(getHRP(), lockPos)
			task.wait(0.5)
			continue
		end
		-- Un seul appel : frappe tout ce qui est dans le rayon autour du centre
		-- Le perso reste sur lockPos, ne bouge plus NPC par NPC
		doDamageCombo(targetName, center, lockPos, 30)
		task.wait(0.21)
	end
end

