		return
	end
	ensureEscapedFishman("Geppo")
	notify("Kaitun", "Buying Geppo...", 5)
	DoSafeTeleport(Vector3.new(-3087.715, 94.544, -11755.474))
	task.wait(1.5)
	pcall(function()
		ReplicatedStorage:WaitForChild("Events"):WaitForChild("learnStyle"):FireServer("skyWalkTrainer")
	end)
	task.wait(2)
end

-- ============================================================

-- PHASE 3: HAKI

-- ============================================================

local function getAllYetis()
	local result = {}
	local folder = workspace:FindFirstChild("NPCs")
	if not folder then return result end
	for _, npc in ipairs(folder:GetChildren()) do
		if npc:IsA("Model") and npc.Name == "Yeti" then
			local hum = npc:FindFirstChild("Humanoid")
			local hrp = npc:FindFirstChild("HumanoidRootPart")
			if hum and hum.Health > 0 and hrp then
				local y = hrp.Position.Y
				if y >= H.YETI_MIN_SAFE_Y and y <= H.YETI_MAX_SAFE_Y then
					table.insert(result, { npc = npc, hrp = hrp })
				end
			end
		end
	end
	return result
end

local function getTargetedYetis()
	local result = {}
	local used = {}
	for _, spot in ipairs(H.YETI_TARGET_SPOTS or {}) do
		if typeof(spot) == "Vector3" then
			local bestNpc = nil
			local bestDist = math.huge
			for _, d in ipairs(getAllYetis()) do
				if d.npc and d.hrp and not used[d.npc] and isInsideYetiZone(d.hrp.Position) then
					local hum = d.npc:FindFirstChild("Humanoid")
					if hum and hum.Health > 0 then
						local dist = (spot - d.hrp.Position).Magnitude
						if dist < bestDist then
							bestDist = dist
							bestNpc = d.npc
						end
					end
				end
			end
			if bestNpc and bestDist <= (H.YETI_TARGET_MAX_DISTANCE or 45) then
				used[bestNpc] = true
				table.insert(result, bestNpc)
			end
		end
	end
	return result
end

local function getClosestYeti()
	local rp = getHRP()
	if not rp then return nil end
	local closest, bestDist = nil, math.huge
	for _, npc in ipairs(getTargetedYetis()) do
		local hrp = npc and npc:FindFirstChild("HumanoidRootPart")
		local hum = npc and npc:FindFirstChild("Humanoid")
		if hrp and hum and hum.Health > 0 then
			local dist = (rp.Position - hrp.Position).Magnitude
			if dist < bestDist then
				closest = npc
				bestDist = dist
			end
		end
	end
	return closest
end

local function shouldAbandonYeti(yetiHrp)
	if not yetiHrp then return true end
	local bestSpotDist = math.huge
	local closestSpot = nil
	for _, spot in ipairs(H.YETI_TARGET_SPOTS or {}) do
		if typeof(spot) == "Vector3" then
			local flatDist = Vector3.new(
				yetiHrp.Position.X - spot.X,
				0,
				yetiHrp.Position.Z - spot.Z
			).Magnitude
			if flatDist < bestSpotDist then
				bestSpotDist = flatDist
				closestSpot = spot
			end
		end
	end
	if not closestSpot then
		return false
	end
	if bestSpotDist > (H.YETI_ABANDON_DISTANCE or 38) then
		return true
	end
	if yetiHrp.Position.Y < closestSpot.Y - (H.YETI_ABANDON_Y_DROP or 25) then
		return true
	end
	return false
end

local function attackYeti(yeti)
	setNoclip(true)
	if not yeti then return false end
	local hum = yeti:FindFirstChild("Humanoid")
	local firstHrp = yeti:FindFirstChild("HumanoidRootPart")
	if not hum or hum.Health <= 0 or not firstHrp then return false end
	local hoverHeight = H.YETI_HOVER_HEIGHT or 8.3
	-- Verrou permanent pendant tout le combat: tant que ce Yeti est vivant,
	-- on reste colle a lui et on continue les combos sans retourner au farmPos.
	local lockActive = true
	local humSelf = getHumanoid()
	if humSelf then humSelf.AutoRotate = false end
	local lockConn = RunService.Heartbeat:Connect(function()
		if not lockActive then return end
		local liveHrp = yeti and yeti:FindFirstChild("HumanoidRootPart")
		local liveHum = yeti and yeti:FindFirstChild("Humanoid")
		local rp = getHRP()
		local hs = getHumanoid()
		if not rp or not hs or hs.Health <= 0 or not liveHrp or not liveHum or liveHum.Health <= 0 then return end
		setNoclip(true)
		hs.AutoRotate = false
		local liveCombatY = liveHrp.Position.Y + hoverHeight
		local cf = getYetiCombatCFrame(liveHrp, liveCombatY, rp)
		if cf then
			local clampedPos = clampToYetiZone(cf.Position)
			local clampedCf = cf - cf.Position + clampedPos
			rp.CFrame = clampedCf
			rp.AssemblyLinearVelocity = Vector3.zero
			rp.AssemblyAngularVelocity = Vector3.zero
		end
	end)
	local killed = false
	local combo = 1
	while getgenv().KaitunFarm and not hasHaki() do
		setNoclip(true)
		local hrp = yeti:FindFirstChild("HumanoidRootPart")
		hum = yeti:FindFirstChild("Humanoid")
		local rp = getHRP()
		if not hrp or not rp or not hum then
			break
		end
		if hum.Health <= 0 then
			killed = true
			break
		end
		local selfHum = getHumanoid()
		if selfHum and selfHum.Health <= (H.HAKI_LOW_HP_THRESHOLD or 100) then
			break
		end
		if shouldAbandonYeti(hrp) then
			break
		end
		local hrpList = { hrp }
		local npcIDs = {}
		local id = getNPCID(yeti)
		if id then table.insert(npcIDs, id) end
		pcall(function()
			local current = getHRP()
			if current then
				local liveCombatY = hrp.Position.Y + hoverHeight
				local cf = getYetiCombatCFrame(hrp, liveCombatY, current)
				if cf then
					current.CFrame = cf - cf.Position + clampToYetiZone(cf.Position)
					current.AssemblyLinearVelocity = Vector3.zero
					current.AssemblyAngularVelocity = Vector3.zero
				end
			end
			combatRegister:InvokeServer({
				[1] = "swingsfx", [2] = "Melee", [3] = combo,
				[4] = "Ground", [5] = false, [6] = CombatAnims[combo],
				[7] = 2, [8] = 1.5,
			})
			current = getHRP()
			local packet = {
				[1] = {
					[1] = "damage", [2] = hrpList, [3] = "Melee",
					[4] = { combo, "Ground", "Melee" }, [5] = true,
					[6] = current and current.CFrame or CFrame.new(hrp.Position.X, hrp.Position.Y + hoverHeight, hrp.Position.Z),
					aircombo = "Ground",
				}
			}
			if #npcIDs > 0 then packet[1].NPCIDs = npcIDs end
			combatRegister:InvokeServer(unpack(packet))
		end)
		combo = combo % 5 + 1
		task.wait(0.18)
	end
	task.wait(0.25)
	lockActive = false
	if lockConn then lockConn:Disconnect() end
	local humEnd = getHumanoid()
	if humEnd then humEnd.AutoRotate = true end
	local after = yeti:FindFirstChild("Humanoid")
	return killed or not after or after.Health <= 0
end

-- ============================================================

-- HAKI OVERLAY

-- ============================================================

local HakiOverlay = {
	kills = 0,
	maxKills = 50,
	status = "tweening",
	gui = nil,
	statusLabel = nil,
	killsLabel = nil,
	updateLoopID = 0,
	cameraHidden = false,
	oldCameraType = nil,
	oldCameraSubject = nil,
	oldCameraCFrame = nil,
	oldCameraFOV = nil,
	cameraConn = nil,
	hudHidden = false,
	hudTransparencyCache = {},

}

local hideHakiOverlay

local function cacheAndSetTransparency(obj, propName, value)
	local ok, oldValue = pcall(function()
		return obj[propName]
	end)
	if not ok then return end
	table.insert(HakiOverlay.hudTransparencyCache, {
		obj = obj,
		prop = propName,
		value = oldValue,
	})
	pcall(function()
		obj[propName] = value
	end)
end

local function makeHudObjectInvisible(obj)
	if not obj then return end
	if obj:IsA("GuiObject") then
		cacheAndSetTransparency(obj, "BackgroundTransparency", 1)
	end
	if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
		cacheAndSetTransparency(obj, "TextTransparency", 1)
		cacheAndSetTransparency(obj, "TextStrokeTransparency", 1)
	end
	if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
		cacheAndSetTransparency(obj, "ImageTransparency", 1)
	end
	if obj:IsA("UIStroke") then
		cacheAndSetTransparency(obj, "Transparency", 1)
	end
end

local function hideHakiHudBars()
	if HakiOverlay.hudHidden then return end
	HakiOverlay.hudHidden = true
	HakiOverlay.hudTransparencyCache = {}
	pcall(function()
		local targets = {}
		local playerGui = LocalPlayer:FindFirstChild("PlayerGui")
		local playerBars = playerGui
			and playerGui:FindFirstChild("HUD")
			and playerGui.HUD:FindFirstChild("Main")
			and playerGui.HUD.Main:FindFirstChild("Bars")
		if playerBars then table.insert(targets, playerBars) end
		local templateBars = ReplicatedStorage:FindFirstChild("GUIS")
			and ReplicatedStorage.GUIS:FindFirstChild("HUD")
			and ReplicatedStorage.GUIS.HUD:FindFirstChild("Main")
			and ReplicatedStorage.GUIS.HUD.Main:FindFirstChild("Bars")
		if templateBars then table.insert(targets, templateBars) end
		for _, root in ipairs(targets) do
			makeHudObjectInvisible(root)
			for _, obj in ipairs(root:GetDescendants()) do
				makeHudObjectInvisible(obj)
			end
		end
	end)
end

local function restoreHakiHudBars()
	if not HakiOverlay.hudHidden then return end
	for i = #HakiOverlay.hudTransparencyCache, 1, -1 do
		local item = HakiOverlay.hudTransparencyCache[i]
		if item and item.obj and item.obj.Parent then
			pcall(function()
				item.obj[item.prop] = item.value
			end)
		end
	end
	HakiOverlay.hudTransparencyCache = {}
	HakiOverlay.hudHidden = false
end

local function hideHakiCamera()
	if HakiOverlay.cameraHidden then return end
	pcall(function()
		local cam = workspace.CurrentCamera
		if not cam then return end
		HakiOverlay.cameraHidden = true
		HakiOverlay.oldCameraType = cam.CameraType
		HakiOverlay.oldCameraSubject = cam.CameraSubject
		HakiOverlay.oldCameraCFrame = cam.CFrame
		HakiOverlay.oldCameraFOV = cam.FieldOfView
		cam.CameraType = Enum.CameraType.Scriptable
		cam.CameraSubject = nil
		cam.FieldOfView = 40
		local privacyCFrame = CFrame.new(-4475.706, 520, -2964.551) * CFrame.Angles(math.rad(-90), 0, 0)
		cam.CFrame = privacyCFrame
		if HakiOverlay.cameraConn then
			HakiOverlay.cameraConn:Disconnect()
		end
		HakiOverlay.cameraConn = RunService.RenderStepped:Connect(function()
			local liveCam = workspace.CurrentCamera
			if liveCam and HakiOverlay.cameraHidden then
				liveCam.CameraType = Enum.CameraType.Scriptable
				liveCam.CFrame = privacyCFrame
			end
		end)
	end)
end

local function restoreHakiCamera()
	if not HakiOverlay.cameraHidden then return end
	pcall(function()
		if HakiOverlay.cameraConn then
			HakiOverlay.cameraConn:Disconnect()
			HakiOverlay.cameraConn = nil
		end
		local cam = workspace.CurrentCamera
		if cam then
			cam.CameraType = HakiOverlay.oldCameraType or Enum.CameraType.Custom
			cam.CameraSubject = HakiOverlay.oldCameraSubject or getHumanoid()
			if HakiOverlay.oldCameraCFrame then
				cam.CFrame = HakiOverlay.oldCameraCFrame
			end
			if HakiOverlay.oldCameraFOV then
				cam.FieldOfView = HakiOverlay.oldCameraFOV
			end
		end
	end)
	HakiOverlay.cameraHidden = false
	HakiOverlay.oldCameraType = nil
	HakiOverlay.oldCameraSubject = nil
	HakiOverlay.oldCameraCFrame = nil
	HakiOverlay.oldCameraFOV = nil
end

local function refreshHakiStatusLabel()
	local statusText = tostring(HakiOverlay.status or "tweening")
	local kills = tonumber(HakiOverlay.kills) or 0
	local maxKills = tonumber(HakiOverlay.maxKills) or 50
	if HakiOverlay.statusLabel then
		HakiOverlay.statusLabel.Text = "Status: " .. statusText
	end
	if HakiOverlay.killsLabel then
		HakiOverlay.killsLabel.Text = "Yeti killed: " .. tostring(kills) .. " / " .. tostring(maxKills)
	end
end

local function showHakiOverlay()
	hideHakiCamera()
	hideHakiHudBars()
	if HakiOverlay.gui and HakiOverlay.gui.Parent then
		HakiOverlay.gui.Enabled = true
		refreshHakiStatusLabel()
		return
	end
	pcall(function()
		local playerGui = LocalPlayer:WaitForChild("PlayerGui")
		local oldCore = CoreGui:FindFirstChild("PrinceHubHakiOverlay")
		if oldCore then oldCore:Destroy() end
		local oldPlayer = playerGui:FindFirstChild("PrinceHubHakiOverlay")
		if oldPlayer then oldPlayer:Destroy() end
		local gui = Instance.new("ScreenGui")
		gui.Name = "PrinceHubHakiOverlay"
		gui.IgnoreGuiInset = true
		gui.ResetOnSpawn = false
		gui.DisplayOrder = 1000
		gui.Parent = playerGui
		local bg = Instance.new("Frame")
		bg.Name = "HakiStatusPanel"
		bg.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
		bg.BackgroundTransparency = 0.25
		bg.BorderSizePixel = 0
		bg.AnchorPoint = Vector2.new(0.5, 0)
		bg.Position = UDim2.fromScale(0.5, 0.04)
		bg.Size = UDim2.fromScale(0.42, 0.16)
		bg.Parent = gui
		local title = Instance.new("TextLabel")
		title.Name = "Title"
		title.BackgroundTransparency = 1
		title.AnchorPoint = Vector2.new(0.5, 0.5)
		title.Position = UDim2.fromScale(0.5, 0.24)
		title.Size = UDim2.fromScale(0.9, 0.28)
		title.Font = Enum.Font.GothamBlack
		title.Text = "Prince Hub"
		title.TextColor3 = Color3.fromRGB(15, 15, 15)
		title.TextScaled = true
		title.Parent = bg
		local statusLabel = Instance.new("TextLabel")
		statusLabel.Name = "Status"
		statusLabel.BackgroundTransparency = 1
		statusLabel.AnchorPoint = Vector2.new(0.5, 0.5)
		statusLabel.Position = UDim2.fromScale(0.5, 0.56)
		statusLabel.Size = UDim2.fromScale(0.9, 0.22)
		statusLabel.Font = Enum.Font.GothamSemibold
		statusLabel.TextColor3 = Color3.fromRGB(30, 30, 30)
		statusLabel.TextScaled = true
		statusLabel.Parent = bg
		local killsLabel = Instance.new("TextLabel")
		killsLabel.Name = "Kills"
		killsLabel.BackgroundTransparency = 1
		killsLabel.AnchorPoint = Vector2.new(0.5, 0.5)
		killsLabel.Position = UDim2.fromScale(0.5, 0.78)
		killsLabel.Size = UDim2.fromScale(0.9, 0.20)
		killsLabel.Font = Enum.Font.GothamBold
		killsLabel.TextColor3 = Color3.fromRGB(30, 30, 30)
		killsLabel.TextScaled = true
		killsLabel.Parent = bg
		HakiOverlay.gui = gui
		HakiOverlay.statusLabel = statusLabel
		HakiOverlay.killsLabel = killsLabel
		refreshHakiStatusLabel()
	end)
	HakiOverlay.updateLoopID = (HakiOverlay.updateLoopID or 0) + 1
	local loopID = HakiOverlay.updateLoopID
	task.spawn(function()
		while HakiOverlay.gui and HakiOverlay.gui.Parent and HakiOverlay.updateLoopID == loopID do
			local questKills, questMax = getHakiQuestProgress(HakiOverlay.kills or 0)
			HakiOverlay.kills = math.clamp(math.floor(tonumber(questKills) or 0), 0, tonumber(questMax) or 50)
			HakiOverlay.maxKills = math.max(1, math.floor(tonumber(questMax) or 50))
			refreshHakiStatusLabel()
			if HakiOverlay.kills >= HakiOverlay.maxKills then
				hideHakiOverlay()
				break
			end
			task.wait(0.25)
		end
	end)
end

local function setHakiStatus(status)
	status = tostring(status or "tweening")
	if status ~= "killing yeti" and status ~= "taking quest" then
		status = "tweening"
	end
	HakiOverlay.status = status
	refreshHakiStatusLabel()
end

local function setHakiKills(kills, maxKills)
	HakiOverlay.kills = math.clamp(math.floor(tonumber(kills) or 0), 0, tonumber(maxKills) or 50)
	HakiOverlay.maxKills = math.max(1, math.floor(tonumber(maxKills) or 50))
	refreshHakiStatusLabel()
	if HakiOverlay.kills >= HakiOverlay.maxKills then
		task.delay(0.5, function()
			hideHakiOverlay()
		end)
	end
end

hideHakiOverlay = function()
	restoreHakiCamera()
	restoreHakiHudBars()
	pcall(function()
		if HakiOverlay.gui then
			HakiOverlay.gui:Destroy()
		end
	end)
	HakiOverlay.gui = nil
	HakiOverlay.statusLabel = nil
	HakiOverlay.killsLabel = nil
	HakiOverlay.updateLoopID = (HakiOverlay.updateLoopID or 0) + 1
end

-- ============================================================

-- HAKI ANTI-KICK TWEEN

-- Vol lÃ©ger en facemouse au lieu d'une montÃ©e haute :

--   - On grimpe juste un peu au-dessus du Y le plus haut entre dÃ©part/arrivÃ©e

--     (assez pour passer arbres bas et muret, pas un saut suspect)

--   - Mouvement direct vers la cible (pas de waypoint flat Ã  100m d'altitude)

--   - FaceMouse permanent : le perso regarde toujours oÃ¹ il va

--   - Step capÃ© par frame, vitesse rÃ©duite pour la phase Haki

-- ============================================================

local function DoHakiTween(targetPos, hoverY)
	if typeof(targetPos) == "CFrame" then targetPos = targetPos.Position end
	if typeof(targetPos) ~= "Vector3" then return end
	-- Clamp la cible dans la zone Yeti pour ne jamais sortir des limites.
	targetPos = clampToYetiZone(targetPos)
	local rp = getHRP()
	local hum = getHumanoid()
	if not rp or not hum or hum.Health <= 0 then return end
	H.tpToken = H.tpToken + 1
	local myToken = H.tpToken
	local startPos = rp.Position
	local finalPos = hoverY and Vector3.new(targetPos.X, hoverY, targetPos.Z) or targetPos
	finalPos = clampToYetiZone(finalPos)
	-- Hauteur de croisiÃ¨re LÃ‰GÃˆRE : juste assez au-dessus pour passer les
	-- petits obstacles (arbres bas, rochers, muret). On prend le max de Y
	-- entre dÃ©part et arrivÃ©e, et on ajoute 10 studs.
	local cruiseY = math.max(startPos.Y, finalPos.Y) + 10
	if cruiseY < H.YETI_MIN_SAFE_Y then cruiseY = H.YETI_MIN_SAFE_Y end
	if cruiseY > H.YETI_MAX_SAFE_Y - 5 then cruiseY = H.YETI_MAX_SAFE_Y - 5 end
	local flatDist = Vector3.new(finalPos.X - startPos.X, 0, finalPos.Z - startPos.Z).Magnitude
	-- Trajectoire :
	-- - petits dÃ©placements (< 8 studs) : direct vers la cible
	-- - sinon : un seul waypoint Ã  hauteur cruiseY juste au-dessus de la
	--   cible (X/Z de la cible, Y = cruiseY), puis la cible. Comme Ã§a on
	--   "glisse" en pente douce de notre position vers le yeti, sans monter
	--   verticalement Ã  100m+.
	local route = {}
	if flatDist > 8 then
		table.insert(route, Vector3.new(finalPos.X, cruiseY, finalPos.Z))
	end
	table.insert(route, finalPos)
	setNoclip(true)
	releaseMovementKeys()
	-- Vitesse rÃ©duite pour la phase Haki.
	local hakiSpeed = math.min(H.teleportSpeed or 70, 55)
	local MAX_STEP_PER_FRAME = 4
	local lastFaceMouse = 0
	local moving = true
	task.spawn(function()
		while moving and H.tpToken == myToken do
			fireTakeStamDash()
			task.wait(0.1)
		end
	end)
	for wpIndex, wp in ipairs(route) do
		local isLast = wpIndex == #route
		local reachDist = isLast and 2.5 or 4
		while H.tpToken == myToken do
			rp = getHRP()
			hum = getHumanoid()
			if not rp or not hum or hum.Health <= 0 then break end
			local cur = rp.Position
			local toWp = wp - cur
			local d = toWp.Magnitude
			if d <= reachDist then
				rp.AssemblyLinearVelocity = Vector3.zero
				rp.AssemblyAngularVelocity = Vector3.zero
				break
			end
			local dt = RunService.Heartbeat:Wait()
			local step = math.min(hakiSpeed * dt, d, MAX_STEP_PER_FRAME)
			local dir = toWp.Unit
			-- FaceMouse permanent (toutes les ~80ms) pour que la rotation
			-- envoyÃ©e au serveur reste cohÃ©rente avec le dÃ©placement.
			if tick() - lastFaceMouse >= 0.08 then
				lastFaceMouse = tick()
				fireFaceMouse()
			end
			local nextPos = cur + dir * step
			-- Clamp Ã  chaque frame: si un step nous fait sortir, on reste Ã 
			-- la limite. Comme Ã§a mÃªme un dt anormal ne peut pas nous Ã©jecter.
			nextPos = clampToYetiZone(nextPos)
			local lookAt = Vector3.new(nextPos.X + dir.X, nextPos.Y, nextPos.Z + dir.Z)
			rp.CFrame = CFrame.lookAt(nextPos, lookAt)
			rp.AssemblyLinearVelocity = Vector3.zero
			rp.AssemblyAngularVelocity = Vector3.zero
		end
	end
	moving = false
	pcall(function()
		local endRp = getHRP()
		local endHum = getHumanoid()
		if endRp then
			setWaterDiveAssist(endRp, endHum, false, finalPos.Y)
		end
	end)
	releaseMovementKeys()
end

local function phase3Haki()
	if not getgenv().KaitunFarm then return end
	if not configFlag("HAKI", "Buso", true) then
		notify("Kaitun", "Buso Haki disabled by config.", 4)
		return
	end
	setNoclip(true)
	ensureEscapedFishman("Haki")
	if hasHaki() then
		notify("Kaitun", "Haki already owned.", 4)
		return
	end
	notify("Kaitun", "Training Haki...", 5)
	showHakiOverlay()
	setHakiStatus("tweening")
	equipMelee()
	local hakiEquipLoop = true
	task.spawn(function()
		while hakiEquipLoop and getgenv().KaitunFarm and not hasHaki() do
			equipMelee()
			task.wait(0.35)
		end
	end)
	local hakiRemote = ReplicatedStorage:WaitForChild("Events"):WaitForChild("Haki")
	local questName = "Road to Armament"
	local questPos = Vector3.new(-4246.068, 169.782, -2990.422)
	local farmPos = Vector3.new(-4475.706, 80.982, -2964.551)
	local function waitAtHakiSpotIfLowHP()
		local hum = getHumanoid()
		if not hum or hum.Health <= 0 then
			return false
		end
		if hum.Health > (H.HAKI_LOW_HP_THRESHOLD or 100) then
			return false
		end
		setHakiStatus("tweening")
		H.tpToken = H.tpToken + 1
		setNoclip(true)
		releaseMovementKeys()
		DoSafeTeleport(farmPos, false, true)
		local rp = getHRP()
		if rp then
			enableAirHold(rp, farmPos)
		end
		local waitUntil = tick() + (H.HAKI_LOW_HP_WAIT or 8)
		while getgenv().KaitunFarm and not hasHaki() and tick() < waitUntil do
			rp = getHRP()
			if rp then
				enableAirHold(rp, farmPos)
				rp.CFrame = CFrame.new(farmPos)
				rp.AssemblyLinearVelocity = Vector3.zero
				rp.AssemblyAngularVelocity = Vector3.zero
			end
			task.wait(0.2)
		end
		return true
	end
	local hakiQuestTried = false
	if getQuest() ~= questName then
		cancelQuestIfDifferent(questName)
		setHakiStatus("tweening")
		DoSafeTeleport(questPos, false, true)
		task.wait(1)
		if getQuest() ~= questName then
			hakiQuestTried = true
			setHakiStatus("taking quest")
			pcall(function()
				questEvent:InvokeServer({ [1] = "takequest", [2] = questName })
			end)
			task.wait(1)
		end
	end
	setHakiStatus("tweening")
	DoSafeTeleport(farmPos, false, true)
	task.wait(0.5)
	-- Synchronise immÃ©diatement le compteur avec la progression cÃ´tÃ© serveur
	-- (utile quand la quÃªte a dÃ©jÃ  des kills enregistrÃ©s, ex. aprÃ¨s un relog).
	local initialKills, initialMax = getHakiQuestProgress(0)
	local kills = initialKills or 0
	setHakiKills(kills, initialMax or 50)
	while getgenv().KaitunFarm and not hasHaki() and kills < 50 do
		local questKills, questMax = getHakiQuestProgress(kills)
		kills = math.max(kills, questKills or 0)
		setHakiKills(kills, questMax or 50)
		if kills >= (questMax or 50) then
			hideHakiOverlay()
			break
		end
		if waitAtHakiSpotIfLowHP() then
			continue
		end
		if markDeathGraceIfNeeded() then
			notify("Kaitun", "Death detected. Waiting 5s before any movement...", 6)
			setHakiStatus("respawning")
			H.tpToken = H.tpToken + 1
			setNoclip(false)
			releaseMovementKeys()
			task.wait(5)
			waitUntilAliveStable(5)
			releaseMovementKeys()
			if not getgenv().KaitunFarm or hasHaki() then break end
			if isOnFishmanIsland() then
				ensureEscapedFishman("Haki respawn")
				if not getgenv().KaitunFarm or hasHaki() then break end
			end
			-- Tween de retour vers Yeti Island, jamais d'instant TP.
			setNoclip(true)
			setHakiStatus("tweening")
			DoSafeTeleport(farmPos, false, true)
			task.wait(0.5)
			continue
		end
		if isOnFishmanIsland() then
			setHakiStatus("respawning")
			ensureEscapedFishman("Haki respawn")
			if not getgenv().KaitunFarm or hasHaki() then break end
			setHakiStatus("tweening")
			DoSafeTeleport(farmPos, false, true)
			task.wait(0.5)
			continue
		end
		if getQuest() ~= questName and not hakiQuestTried then
			hakiQuestTried = true
			cancelQuestIfDifferent(questName)
			setHakiStatus("tweening")
			DoSafeTeleport(questPos, false, true)
			task.wait(1)
			setHakiStatus("taking quest")
			pcall(function()
				questEvent:InvokeServer({ [1] = "takequest", [2] = questName })
			end)
			task.wait(1)
			setHakiStatus("tweening")
			DoSafeTeleport(farmPos, false, true)
		end
		setNoclip(true)
		equipMelee()
		pcall(function() hakiRemote:FireServer("Buso") end)
		if tick() < (H.respawnGraceUntil or 0) then
			releaseMovementKeys()
			task.wait(0.5)
			continue
		end
		local yeti = getClosestYeti()
		if not yeti then
			if isOnFishmanIsland() then
				setHakiStatus("respawning")
				ensureEscapedFishman("Haki no Yeti")
				if not getgenv().KaitunFarm or hasHaki() then break end
			end
			setHakiStatus("tweening")
			DoSafeTeleport(farmPos, false, true)
			task.wait(2)
			continue
		end
		local hrp = yeti:FindFirstChild("HumanoidRootPart")
		if hrp then
			if hrp.Position.Y < H.YETI_MIN_SAFE_Y or hrp.Position.Y > H.YETI_MAX_SAFE_Y then
				task.wait(0.5)
				continue
			end
			-- Tween simple de yeti en yeti (pas d'instant TP, pas d'arc).
			setHakiStatus("tweening")
			local hoverPos = Vector3.new(hrp.Position.X, hrp.Position.Y + (H.YETI_HOVER_HEIGHT or 8.3), hrp.Position.Z)
			DoHakiTween(hoverPos)
			setHakiStatus("killing yeti")
			local killed = attackYeti(yeti)
			if waitAtHakiSpotIfLowHP() then
				continue
			end
			if killed then
				kills = kills + 1
				local questKills2, qmax2 = getHakiQuestProgress(kills)
				kills = math.max(kills, questKills2 or kills)
				setHakiKills(kills, qmax2 or 50)
			end
		end
		task.wait(0.21)
	end
	hakiEquipLoop = false
	setNoclip(false)
	hideHakiOverlay()
end

-- ============================================================

-- PHASE 4: WORLD SCROLL

-- ============================================================

local function phase4WorldScroll()
	if not getgenv().KaitunFarm then return end
	if not configFlag("ITEM", "World Scroll", true) then
		notify("Kaitun", "World Scroll disabled by config.", 4)
		return
	end
	ensureEscapedFishman("World Scroll")
	if hasWorldScroll() then
		notify("Kaitun", "World Scroll already owned.", 4)
		return
	end
	local scrollPos = Vector3.new(-7348.136, 3.274, -14951.547)
	local attempts = 0
	while getgenv().KaitunFarm and not hasWorldScroll() do
		attempts = attempts + 1
		if markDeathGraceIfNeeded() then
			notify("World Scroll", "Death detected. Waiting 10s, then retrying World Scroll...", 6)
			H.tpToken = H.tpToken + 1
			setNoclip(false)
			releaseMovementKeys()
			task.wait(10)
			waitUntilAliveStable(5)
			releaseMovementKeys()
		end
		if isOnFishmanIsland() then
			ensureEscapedFishman("World Scroll respawn")
			if not getgenv().KaitunFarm then break end
		end
		if hasWorldScroll() then break end
		notify("Kaitun", "Getting World Scroll... Attempt " .. tostring(attempts), 5)
		DoSafeTeleport(scrollPos)
		task.wait(0.5)
		if markDeathGraceIfNeeded() then
			notify("World Scroll", "Died during World Scroll path. Retrying after respawn...", 6)
			H.tpToken = H.tpToken + 1
			setNoclip(false)
			releaseMovementKeys()
			task.wait(10)
			waitUntilAliveStable(5)
			releaseMovementKeys()
			continue
		end
		pcall(function()
			VirtualInput:SendKeyEvent(true, Enum.KeyCode.LeftAlt, false, game)
			task.wait(3)
			VirtualInput:SendKeyEvent(false, Enum.KeyCode.LeftAlt, false, game)
		end)
		task.wait(1)
	end
	if hasWorldScroll() then
		notify("Kaitun", "World Scroll obtained.", 5)
	else
		notify("Kaitun", "World Scroll not confirmed. Staying in World Scroll phase, no main menu.", 8)
		getgenv().KaitunFarm = false
	end
end

-- ============================================================

-- PHASE 5: MAIN MENU THEN SEA 2

-- ============================================================

local function phase5MainMenuSea2()
	if not getgenv().KaitunFarm then return end
	if configFlag("ITEM", "World Scroll", true) and not hasWorldScroll() then
		notify("Kaitun", "World Scroll not in inventory. Main menu blocked.", 8)
		getgenv().KaitunFarm = false
		return
	end
	local code = getActivePSCode()
	if code == "" then
		notify("Kaitun Sea 2", "No PS code set. Main menu blocked.", 8)
		getgenv().KaitunFarm = false
		return
	end
	savePSCode(code)
	getgenv().KaitunSea2Code = code
	getgenv().KaitunSea2Pending = true
	notify("Kaitun", "Going main menu for Sea 2...", 5)
	task.wait(1)
	pcall(function()
		TeleportService:Teleport(LOGIN_PLACE_ID, LocalPlayer)
	end)
end

-- ============================================================

-- SEA 2 FARM: CRAZY WOLF TO 675

-- ============================================================

local S2 = { running = false, loopID = 0, upHeight = 9, canAttack = true }

local function setSea2Spawn()
	local setSpawnRemote = ReplicatedStorage:WaitForChild("Events"):WaitForChild("SetSpawn")
	local spawnPos = Vector3.new(7319.132, 21.723, 10561.868)
	DoSafeTeleport(spawnPos)
	task.wait(1)
	pcall(function() setSpawnRemote:FireServer() end)
	task.wait(0.5)
end

local function getCrazyWolvesNear(pos, radius)
	local result = {}
	radius = radius or 22
	for _, d in ipairs(getAllNPCs("Crazy Wolf")) do
		if d.hrp and (d.hrp.Position - pos).Magnitude <= radius then
			table.insert(result, d)
		end
	end
	return result
end

local function attackWolf(wolf)
	if not S2.canAttack then return end
	local hum = wolf and wolf:FindFirstChild("Humanoid")
	local hrp = wolf and wolf:FindFirstChild("HumanoidRootPart")
	if not hum or hum.Health <= 0 or not hrp then return end
	S2.canAttack = false
	equipMelee()
	local lockActive = true
	local lockConn = RunService.Heartbeat:Connect(function()
		if not lockActive then return end
		local liveHrp = wolf and wolf:FindFirstChild("HumanoidRootPart")
		local liveHum = wolf and wolf:FindFirstChild("Humanoid")
		local rp = getHRP()
		local selfHum = getHumanoid()
		if not liveHrp or not liveHum or liveHum.Health <= 0 or not rp or not selfHum or selfHum.Health <= 0 then
			return
		end
		setNoclip(true)
		local standPos = Vector3.new(liveHrp.Position.X, liveHrp.Position.Y + S2.upHeight, liveHrp.Position.Z)
		enableAirHold(rp, standPos)
		selfHum.AutoRotate = false
		selfHum.PlatformStand = false
		selfHum.Sit = false
		rp.CFrame = CFrame.new(standPos)
		rp.AssemblyLinearVelocity = Vector3.zero
		rp.AssemblyAngularVelocity = Vector3.zero
	end)
	for combo = 1, 5 do
		if not getgenv().Sea2Farm then break end
		hrp = wolf:FindFirstChild("HumanoidRootPart")
		hum = wolf:FindFirstChild("Humanoid")
		local rp = getHRP()
		if not hrp or not hum or hum.Health <= 0 or not rp then break end
		local npcPos = hrp.Position
		local standPos = Vector3.new(npcPos.X, npcPos.Y + S2.upHeight, npcPos.Z)
		enableAirHold(rp, standPos)
		rp.CFrame = CFrame.new(standPos)
		rp.AssemblyLinearVelocity = Vector3.zero
		rp.AssemblyAngularVelocity = Vector3.zero
		local hrpList = {}
		local npcIDs = {}
		for _, d in ipairs(getCrazyWolvesNear(npcPos, 22)) do
			table.insert(hrpList, d.hrp)
			local id = getNPCID(d.npc)
			if id then table.insert(npcIDs, id) end
		end
		if #hrpList == 0 then
			table.insert(hrpList, hrp)
			local id = getNPCID(wolf)
			if id then table.insert(npcIDs, id) end
		end
		pcall(function()
			local current = getHRP()
			local liveHrp = wolf and wolf:FindFirstChild("HumanoidRootPart")
			if current and liveHrp then
				local liveStandPos = Vector3.new(liveHrp.Position.X, liveHrp.Position.Y + S2.upHeight, liveHrp.Position.Z)
				enableAirHold(current, liveStandPos)
				current.CFrame = CFrame.new(liveStandPos)
				current.AssemblyLinearVelocity = Vector3.zero
				current.AssemblyAngularVelocity = Vector3.zero
			end
			combatRegister:InvokeServer({
				[1] = "swingsfx", [2] = "Melee", [3] = combo,
				[4] = "Ground", [5] = false, [6] = CombatAnims[combo],
				[7] = combo == 1 and 2 or 1.75, [8] = 1.5,
			})
			current = getHRP()
			liveHrp = wolf and wolf:FindFirstChild("HumanoidRootPart")
			if current and liveHrp then
				local liveStandPos = Vector3.new(liveHrp.Position.X, liveHrp.Position.Y + S2.upHeight, liveHrp.Position.Z)
				enableAirHold(current, liveStandPos)
				current.CFrame = CFrame.new(liveStandPos)
				current.AssemblyLinearVelocity = Vector3.zero
				current.AssemblyAngularVelocity = Vector3.zero
			end
			local packet = {
				[1] = {
					[1] = "damage", [2] = hrpList, [3] = "Melee",
					[4] = { combo, "Ground", "Melee" }, [5] = true,
					[6] = current and current.CFrame or rp.CFrame,
					aircombo = "Ground",
				}
			}
			if #npcIDs > 0 then packet[1].NPCIDs = npcIDs end
			combatRegister:InvokeServer(unpack(packet))
		end)
		task.wait(0.21)
	end
	lockActive = false
	if lockConn then lockConn:Disconnect() end
	local humEnd = getHumanoid()
	if humEnd then
		humEnd.AutoRotate = true
	end
	disableAirHold()
	task.wait(1)
	S2.canAttack = true
end

function H.startSea2Farm()
	if S2.running then return end
	if not IS_SEA2_PLACE then
		startAutoJoinSea2(getActivePSCode())
		return
	end
	-- Ne pas verifier PrivateServerId ici: le retour main menu est gere uniquement
	-- par le flag Fatal Error / 267 dans shouldForceMainMenuFromCurrentPlace().
	S2.running = true
	S2.loopID = S2.loopID + 1
	local loopID = S2.loopID
	getgenv().Sea2Farm = true
	H.autoAdsEnabled = true
	H.autoStatsEnabled = true
	setNoclip(true)
	H.teleportSpeed = DefaultConfig.MAIN.TWEEN_SPEED or 70
	notify("Sea 2", "Crazy Wolf farm started.", 5)
	task.spawn(function()
		setSea2Spawn()
		local questName = "Help PJ"
		local questPos = Vector3.new(7121.167, 56.273, 10553.389)
		local center = Vector3.new(7319.132, 21.723, 10561.868)
		local maxLevel = DefaultConfig.MAIN.LEVEL or 675
		while getgenv().Sea2Farm and S2.loopID == loopID do
			if not isAlive() then task.wait(0.5) continue end
			if getLevel() >= maxLevel then
				notify("Sea 2", "Level " .. tostring(maxLevel) .. " reached.", 6)
				break
			end
			equipMelee()
			if getQuest() ~= questName and getLevel() >= 425 then
				takeQuest(questName, questPos)
				task.wait(0.5)
				continue
			end
			local wolf = getClosestNPC("Crazy Wolf")
			local rp = getHRP()
			if not rp then task.wait(0.5) continue end
			if not wolf then
				local centerPos = Vector3.new(center.X, center.Y + S2.upHeight, center.Z)
				if (rp.Position - centerPos).Magnitude > 8 then
					DoSafeTeleport(centerPos, true)
				end
				task.wait(0.5)
				continue
			end
			local hrp = wolf:FindFirstChild("HumanoidRootPart")
			if hrp then
				local standPos = Vector3.new(hrp.Position.X, hrp.Position.Y + S2.upHeight, hrp.Position.Z)
				if (rp.Position - standPos).Magnitude > 8 then
					DoSafeTeleport(standPos, true)
				end
				task.wait(0.03)
				attackWolf(wolf)
			end
			task.wait(0.21)
		end
		getgenv().Sea2Farm = false
		S2.running = false
		H.autoAdsEnabled = false
		H.autoStatsEnabled = false
		notify("Sea 2", "Farm stopped.", 4)
	end)
end

function H.stopSea2Farm()
	getgenv().Sea2Farm = false
	S2.running = false
	S2.loopID = S2.loopID + 1
	S2.canAttack = true
	H.tpToken = H.tpToken + 1
end

-- ============================================================

-- AUTO KAITUN MAIN FLOW

-- ============================================================

local KT = { running = false, loopID = 0 }

function H.startKaitunFarm()
	if KT.running then return end
	notify("Kaitun", "Start clicked | Level: " .. tostring(getLevel()) .. " | PlaceId: " .. tostring(game.PlaceId), 5)
	if IS_LOGIN_PLACE then
		startAutoJoinSea2(getActivePSCode())
		return
	end
	KT.running = true
	KT.loopID = KT.loopID + 1
	getgenv().KaitunFarm = true
	startUtilityLoops()
	H.autoAdsEnabled = true
	H.autoStatsEnabled = true
	setNoclip(true)
	H.teleportSpeed = DefaultConfig.MAIN.TWEEN_SPEED or 70
	task.spawn(function()
		local ok, err = pcall(function()
			if shouldForceMainMenuFromCurrentPlace() then
				teleportToMainMenuForPS()
				return
			end
			if IS_SEA2_PLACE then
				H.startSea2Farm()
				while KT.running and getgenv().Sea2Farm do
					if getLevel() >= (DefaultConfig.MAIN.LEVEL or 675) then
						H.stopSea2Farm()
						break
					end
					task.wait(3)
				end
			else
				local level = getLevel()
				notify("Kaitun", "Main flow running | Level: " .. tostring(level), 5)
				if level < 425 then
					notify("Kaitun", "Level < 425, starting Fishman farm.", 5)
					phase1FishmanFarm()
				else
					notify("Kaitun", "Level >= 425, skipping Fishman farm.", 5)
				end
				if KT.running and configFlag("STYLE", "Geppo", true) then
					getgenv().KaitunFarm = true
					ensureEscapedFishman("Before Geppo")
					phase2Geppo()
				end
				if KT.running and configFlag("HAKI", "Buso", true) then
					getgenv().KaitunFarm = true
					ensureEscapedFishman("Before Haki")
					phase3Haki()
				end
				if KT.running and configFlag("ITEM", "World Scroll", true) then
					getgenv().KaitunFarm = true
					ensureEscapedFishman("Before World Scroll")
					phase4WorldScroll()
				end
				if KT.running then
					getgenv().KaitunFarm = true
					phase5MainMenuSea2()
				end
			end
		end)
		KT.running = false
		getgenv().KaitunFarm = false
		H.autoAdsEnabled = false
		H.autoStatsEnabled = false
		releaseMovementKeys()
		if ok then
			notify("Kaitun", "Stopped.", 4)
		else
			notify("Kaitun ERROR", tostring(err), 10)
		end
	end)
end

function H.stopKaitunFarm()
	KT.running = false
	getgenv().KaitunFarm = false
	H.autoAdsEnabled = false
	H.autoStatsEnabled = false
	H.tpToken = H.tpToken + 1
	if H.stopSea2Farm then H.stopSea2Farm() end
	releaseMovementKeys()
	notify("Kaitun", "Stopped manually.", 4)
end

-- ============================================================

-- BOOT

-- ============================================================

startUtilityLoops()

notify("Prince Hub", "Kaitun-only loaded.", 4)

if DefaultConfig.MAIN.AUTO_JOIN_SEA2 or getgenv().KaitunSea2Pending then
	task.spawn(function()
		task.wait(3)
		local code = getActivePSCode()
		if IS_LOGIN_PLACE then
			clearMainMenuAfterRejoin()
			startAutoJoinSea2(code)
		elseif shouldForceMainMenuFromCurrentPlace() then
			teleportToMainMenuForPS()
			return
		elseif IS_SEA2_PLACE then
			getgenv().KaitunSea2Pending = false
			H.startSea2Farm()
		end
	end)
end

if DefaultConfig.MAIN.AUTO_KAITUN then
	task.spawn(function()
		task.wait(2)
		H.startKaitunFarm()
	end)
end

getgenv().PrinceKaitunOnly = H

end -- END MODULE: Kaitun

