	CFG = CFG,
}
getgenv().PrinceWaves = W

local S = {
	loopId = 0,
	inArena = false,
	home = nil,     -- وين كنت واگف قبل أول NPC (يرجع له بين الأمواج)
	homeGrounded = false,
	floorY = nil,   -- ارتفاع أرض الساحة (ينعرف لما توگف على الأرض) حتى نتجاهل NPC واگع بالفراغ
	hadTarget = false,
	resting = false,
	idleSince = nil,

	armed = false,
	waveFresh = false,
	lastWave = nil,
	waveHighSince = nil,

	combo = 0,
	nextAttackAt = 0,
	radius = 100,
	radiusBase = nil,

	target = nil,
	targetSince = 0,
	arrivedAt = nil,
	progressAt = 0,
	lastHitCount = 0,
	noDamage = false,
	radiusRestoreAt = nil,
	radiusRestoredAt = nil,
	restoreDelay = nil,
	blacklist = {},
	blackCount = {},
	seen = {},      -- [npc] = آخر Health شفناه
	mates = nil,

	aliveSince = 0,
	lastChar = nil,
	wasDead = false,
	selfRespawn = false,

	busoChar = nil,
	weaponInfo = nil,
