	if misc.FpsCap and tonumber(misc.FpsCap) and tonumber(misc.FpsCap) > 0 then
		pcall(setfpscap, tonumber(misc.FpsCap))
	end
	if misc.FastMode then
		runFastMode()
	end
	if misc.WebhookURL and misc.WebhookURL ~= "" and misc.WebhookURL ~= "YourURL" then
		getgenv().WebHook = misc.WebhookURL
	end
end

