				game:GetService("TeleportService"):Teleport(6360478118, game:GetService("Players").LocalPlayer)
			end)
			task.wait(0.1)
		end
	else
		if player.AccountAge > 30 then
			for i = 1, 500 do
				if not W.enabled then break end
				pcall(function()
					game:GetService("TeleportService"):Teleport(6360478118, game:GetService("Players").LocalPlayer)
				end)
				task.wait(0.1)
			end
		else
			local function JoinPS(PS)
				while task.wait(0.5) do
					if not W.enabled then continue end
					spawn(function()
						if not PS then
							return
						end

						local TextBox = PlayerGui.reserved.Frame.CodeBox.TextBox

						local ChooseType = PlayerGui:WaitForChild("chooseType", 2)
						local ChooseSea = PlayerGui:WaitForChild("ConfirmationPrompt", 5)

						if ChooseType then
							spawn(function()
								local reg = ChooseType.Frame.Options.Universe
								if reg then
									local args = {
										"universeHub",
									}
									PlayerGui:WaitForChild("chooseType")
										:WaitForChild("Frame")
										:WaitForChild("RemoteEvent")
										:FireServer(unpack(args))
								end
							end)
						else
							TextBox.Text = PS
							local args = { [1] = PS }
							game:GetService("ReplicatedStorage")
								:WaitForChild("Events")
								:WaitForChild("reserved")
								:InvokeServer(unpack(args))
						end
					end)
				end
			end

			if ZConfig and ZConfig.Misc and ZConfig.Misc.PsCode then
				JoinPS(ZConfig.Misc.PsCode)
			end
		end
	end
end

