		Others.GeppoCooldown = 2

		function UseGeppo()
			Others.LastGeppo = true
			task.delay(Others.GeppoCooldown, function()
				Others.LastGeppo = false
			end)
			for i = 1, 2 do
				local args = {
					false,
				}
				game:GetService("ReplicatedStorage")
					:WaitForChild("Events")
					:WaitForChild("faceMouse")
