	function Library:SetWatermarkVisibility(Bool)
		Library.Watermark.Visible = Bool;
	end;

	function Library:SetWatermark(Text)
		local X, Y = Library:GetTextBounds(Text, Library.Font, 14);
		Library.Watermark.Size = UDim2.new(0, X + 15, 0, (Y * 1.5) + 3);
		Library:SetWatermarkVisibility(true)

		Library.WatermarkText.Text = Text;
	end;

	function Library:Notify(Text, Time)
		local XSize, YSize = Library:GetTextBounds(Text, Library.Font, 14);

		YSize = YSize + 7

		local NotifyOuter = Library:Create('Frame', {
			BorderColor3 = Color3.new(0, 0, 0);
			Position = UDim2.new(0, 100, 0, 10);
			Size = UDim2.new(0, 0, 0, YSize);
			ClipsDescendants = true;
			ZIndex = 100;
			Parent = Library.NotificationArea;
		});

		local NotifyInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 101;
			Parent = NotifyOuter;
		});

		Library:AddToRegistry(NotifyInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		}, true);

		local InnerFrame = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(1, 1, 1);
			BorderSizePixel = 0;
			Position = UDim2.new(0, 1, 0, 1);
			Size = UDim2.new(1, -2, 1, -2);
			ZIndex = 102;
			Parent = NotifyInner;
		});

		local Gradient = Library:Create('UIGradient', {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Library:GetDarkerColor(Library.MainColor)),
				ColorSequenceKeypoint.new(1, Library.MainColor),
			});
			Rotation = -90;
			Parent = InnerFrame;
		});

		Library:AddToRegistry(Gradient, {
			Color = function()
				return ColorSequence.new({
					ColorSequenceKeypoint.new(0, Library:GetDarkerColor(Library.MainColor)),
					ColorSequenceKeypoint.new(1, Library.MainColor),
				});
			end
		});

		local NotifyLabel = Library:CreateLabel({
			Position = UDim2.new(0, 4, 0, 0);
			Size = UDim2.new(1, -4, 1, 0);
			Text = Text;
			TextXAlignment = Enum.TextXAlignment.Left;
			TextSize = 14;
			ZIndex = 103;
			Parent = InnerFrame;
		});

		local LeftColor = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderSizePixel = 0;
			Position = UDim2.new(0, -1, 0, -1);
			Size = UDim2.new(0, 3, 1, 2);
			ZIndex = 104;
			Parent = NotifyOuter;
		});

		Library:AddToRegistry(LeftColor, {
			BackgroundColor3 = 'AccentColor';
		}, true);

		pcall(NotifyOuter.TweenSize, NotifyOuter, UDim2.new(0, XSize + 8 + 4, 0, YSize), 'Out', 'Quad', 0.4, true);

		task.spawn(function()
			wait(Time or 5);

			pcall(NotifyOuter.TweenSize, NotifyOuter, UDim2.new(0, 0, 0, YSize), 'Out', 'Quad', 0.4, true);

			wait(0.4);

			NotifyOuter:Destroy();
		end);
	end;

	function Library:CreateWindow(...)
		local Arguments = { ... }
		local Config = { AnchorPoint = Vector2.zero }

		if type(...) == 'table' then
			Config = ...;
		else
			Config.Title = Arguments[1]
			Config.AutoShow = Arguments[2] or false;
		end

		if type(Config.Title) ~= 'string' then Config.Title = 'No title' end
		if type(Config.TabPadding) ~= 'number' then Config.TabPadding = 0 end
		if type(Config.MenuFadeTime) ~= 'number' then Config.MenuFadeTime = 0.2 end

		if typeof(Config.Position) ~= 'UDim2' then Config.Position = UDim2.fromOffset(175, 50) end
		if typeof(Config.Size) ~= 'UDim2' then Config.Size = UDim2.fromOffset(550, 600) end

		if Config.Center then
			Config.AnchorPoint = Vector2.new(0.5, 0.5)
			Config.Position = UDim2.fromScale(0.5, 0.5)
		end

		local Window = {
			Tabs = {};
		};

		local Outer = Library:Create('Frame', {
			AnchorPoint = Config.AnchorPoint,
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderSizePixel = 0;
			Position = Config.Position,
			Size = Config.Size,
			Visible = false;
			ZIndex = 1;
			Parent = ScreenGui;
		});

		Library:MakeDraggable(Outer, 25);
		Library.MainWindowFrame = Outer; -- [PRINCE HUB] used by X button / mini square

		local Inner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.AccentColor;
			BorderMode = Enum.BorderMode.Inset;
			Position = UDim2.new(0, 1, 0, 1);
			Size = UDim2.new(1, -2, 1, -2);
			ZIndex = 1;
			ClipsDescendants = true;
			Parent = Outer;
		});

		Library:AddToRegistry(Inner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'AccentColor';
		});

		local WindowLabel = Library:CreateLabel({
			Position = UDim2.new(0, 7, 0, 0);
			Size = UDim2.new(0, 0, 0, 25);
			Text = Config.Title or '';
			TextXAlignment = Enum.TextXAlignment.Left;
			ZIndex = 1;
			Parent = Inner;
		});

		local MainSectionOuter = Library:Create('Frame', {
			BackgroundColor3 = Library.BackgroundColor;
			BorderColor3 = Library.OutlineColor;
			Position = UDim2.new(0, 8, 0, 25);
			Size = UDim2.new(1, -16, 1, -33);
			ZIndex = 1;
			Parent = Inner;
		});

		Library:AddToRegistry(MainSectionOuter, {
			BackgroundColor3 = 'BackgroundColor';
			BorderColor3 = 'OutlineColor';
		});

		local MainSectionInner = Library:Create('Frame', {
			BackgroundColor3 = Library.BackgroundColor;
			BorderColor3 = Color3.new(0, 0, 0);
			BorderMode = Enum.BorderMode.Inset;
			Position = UDim2.new(0, 0, 0, 0);
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 1;
			Parent = MainSectionOuter;
		});

		Library:AddToRegistry(MainSectionInner, {
			BackgroundColor3 = 'BackgroundColor';
		});

		-- [PRINCE HUB] شريط التبويبات صار سكرول أفقي (اسحب يمين/يسار) + أسهم < >
		local TAB_ARROW_W = 14;
		local TabArea = Library:Create('ScrollingFrame', {
			Name = 'PrinceTabBar';
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Position = UDim2.new(0, 8 + TAB_ARROW_W + 2, 0, 8);
			Size = UDim2.new(1, -16 - (TAB_ARROW_W + 2) * 2, 0, 22);
			CanvasSize = UDim2.new(0, 0, 0, 0);
			ScrollingDirection = Enum.ScrollingDirection.X;
			ScrollBarThickness = 0;
			BottomImage = '';
			TopImage = '';
			ElasticBehavior = Enum.ElasticBehavior.Never;
			ClipsDescendants = true;
			ZIndex = 1;
			Parent = MainSectionInner;
		});

		local TabListLayout = Library:Create('UIListLayout', {
			Padding = UDim.new(0, Config.TabPadding);
			FillDirection = Enum.FillDirection.Horizontal;
			SortOrder = Enum.SortOrder.LayoutOrder;
			Parent = TabArea;
		});

		local function PrinceTabBarView()
			local sc = Library.UIScale or 1;
			local view = TabArea.AbsoluteSize.X / sc;
			local total = TabListLayout.AbsoluteContentSize.X / sc;
			return view, total, math.max(0, total - view);
		end;

		local function PrinceTabBarScrollTo(x)
			local _, _, maxX = PrinceTabBarView();
			TabArea.CanvasPosition = Vector2.new(math.clamp(x, 0, maxX), 0);
		end;

		TabListLayout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
			pcall(function()
				local _, total = PrinceTabBarView();
				TabArea.CanvasSize = UDim2.fromOffset(total, 0);
				PrinceTabBarScrollTo(TabArea.CanvasPosition.X);
			end);
		end);

		for _, ArrowInfo in ipairs({ { '<', -1, UDim2.new(0, 8, 0, 8) }, { '>', 1, UDim2.new(1, -8 - TAB_ARROW_W, 0, 8) } }) do
			local Arrow = Library:Create('TextButton', {
				Name = 'PrinceTabArrow';
				AutoButtonColor = false;
				BackgroundColor3 = Library.BackgroundColor;
				BorderColor3 = Library.OutlineColor;
				Position = ArrowInfo[3];
				Size = UDim2.new(0, TAB_ARROW_W, 0, 21);
				Font = Library.Font;
				Text = ArrowInfo[1];
				TextColor3 = Library.FontColor;
				TextSize = 14;
				ZIndex = 1;
				Parent = MainSectionInner;
			});
			Library:AddToRegistry(Arrow, {
				BackgroundColor3 = 'BackgroundColor';
				BorderColor3 = 'OutlineColor';
				TextColor3 = 'FontColor';
			});
			local dir = ArrowInfo[2];
			Arrow.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
					pcall(function()
						local view = PrinceTabBarView();
						PrinceTabBarScrollTo(TabArea.CanvasPosition.X + dir * math.max(60, view * 0.6));
					end);
				end;
			end);
		end;

		local TabContainer = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			Position = UDim2.new(0, 8, 0, 30);
			Size = UDim2.new(1, -16, 1, -38);
			ZIndex = 2;
			Parent = MainSectionInner;
		});


		Library:AddToRegistry(TabContainer, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		});

		function Window:SetWindowTitle(Title)
			WindowLabel.Text = Title;
		end;

		function Window:AddTab(Name)
			local Tab = {
				Groupboxes = {};
				Tabboxes = {};
			};

			local TabButtonWidth = Library:GetTextBounds(Name, Library.Font, 16);

			local TabButton = Library:Create('Frame', {
				BackgroundColor3 = Library.BackgroundColor;
				BorderColor3 = Library.OutlineColor;
				Size = UDim2.new(0, TabButtonWidth + 8 + 4, 0, 21);
				ZIndex = 1;
				Parent = TabArea;
			});

			Library:AddToRegistry(TabButton, {
				BackgroundColor3 = 'BackgroundColor';
				BorderColor3 = 'OutlineColor';
			});

			local TabButtonLabel = Library:CreateLabel({
				Position = UDim2.new(0, 0, 0, 0);
				Size = UDim2.new(1, 0, 1, -1);
				Text = Name;
				ZIndex = 1;
				Parent = TabButton;
			});

			local Blocker = Library:Create('Frame', {
				BackgroundColor3 = Library.MainColor;
				BorderSizePixel = 0;
				Position = UDim2.new(0, 0, 1, 0);
				Size = UDim2.new(1, 0, 0, 1);
				BackgroundTransparency = 1;
				ZIndex = 3;
				Parent = TabButton;
			});

			Library:AddToRegistry(Blocker, {
				BackgroundColor3 = 'MainColor';
			});

			local TabFrame = Library:Create('Frame', {
				Name = 'TabFrame',
				BackgroundTransparency = 1;
				Position = UDim2.new(0, 0, 0, 0);
				Size = UDim2.new(1, 0, 1, 0);
				Visible = false;
				ZIndex = 2;
				Parent = TabContainer;
			});

			local LeftSide = Library:Create('ScrollingFrame', {
				BackgroundTransparency = 1;
				BorderSizePixel = 0;
				Position = UDim2.new(0, 8 - 1, 0, 8 - 1);
				Size = UDim2.new(0.5, -12 + 2, 0, 507 + 2);
				CanvasSize = UDim2.new(0, 0, 0, 0);
				BottomImage = '';
				TopImage = '';
				ScrollBarThickness = 0;
				ZIndex = 2;
				Parent = TabFrame;
			});

			local RightSide = Library:Create('ScrollingFrame', {
				BackgroundTransparency = 1;
				BorderSizePixel = 0;
				Position = UDim2.new(0.5, 4 + 1, 0, 8 - 1);
				Size = UDim2.new(0.5, -12 + 2, 0, 507 + 2);
				CanvasSize = UDim2.new(0, 0, 0, 0);
				BottomImage = '';
				TopImage = '';
				ScrollBarThickness = 0;
				ZIndex = 2;
				Parent = TabFrame;
			});

			Library:Create('UIListLayout', {
				Padding = UDim.new(0, 8);
				FillDirection = Enum.FillDirection.Vertical;
				SortOrder = Enum.SortOrder.LayoutOrder;
				HorizontalAlignment = Enum.HorizontalAlignment.Center;
				Parent = LeftSide;
			});

			Library:Create('UIListLayout', {
				Padding = UDim.new(0, 8);
				FillDirection = Enum.FillDirection.Vertical;
				SortOrder = Enum.SortOrder.LayoutOrder;
				HorizontalAlignment = Enum.HorizontalAlignment.Center;
				Parent = RightSide;
			});

			for _, Side in next, { LeftSide, RightSide } do
				Side:WaitForChild('UIListLayout'):GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
					Side.CanvasSize = UDim2.fromOffset(0, Side.UIListLayout.AbsoluteContentSize.Y / (Library.UIScale or 1)); -- [PRINCE HUB] UIScale (scroll to the bottom)
				end);
			end;

			function Tab:ShowTab()
				for _, Tab in next, Window.Tabs do
					Tab:HideTab();
				end;

				Blocker.BackgroundTransparency = 0;
				TabButton.BackgroundColor3 = Library.MainColor;
				Library.RegistryMap[TabButton].Properties.BackgroundColor3 = 'MainColor';
				TabFrame.Visible = true;

				-- [PRINCE HUB] نخلي التبويب المختار ظاهر بالشريط
				pcall(function()
					local sc = Library.UIScale or 1;
					local view = PrinceTabBarView();
					local cx = TabArea.CanvasPosition.X;
					local left = (TabButton.AbsolutePosition.X - TabArea.AbsolutePosition.X) / sc + cx;
					local w = TabButton.AbsoluteSize.X / sc;
					if left < cx then
						PrinceTabBarScrollTo(left);
					elseif left + w > cx + view then
						PrinceTabBarScrollTo(left + w - view);
					end;
				end);
			end;

			function Tab:HideTab()
				Blocker.BackgroundTransparency = 1;
				TabButton.BackgroundColor3 = Library.BackgroundColor;
				Library.RegistryMap[TabButton].Properties.BackgroundColor3 = 'BackgroundColor';
				TabFrame.Visible = false;
			end;

			function Tab:SetLayoutOrder(Position)
				TabButton.LayoutOrder = Position;
				TabListLayout:ApplyLayout();
			end;

			function Tab:AddGroupbox(Info)
				local Groupbox = {};

				local BoxOuter = Library:Create('Frame', {
					BackgroundColor3 = Library.BackgroundColor;
					BorderColor3 = Library.OutlineColor;
					BorderMode = Enum.BorderMode.Inset;
					Size = UDim2.new(1, 0, 0, 507 + 2);
					ZIndex = 2;
					Parent = Info.Side == 1 and LeftSide or RightSide;
				});

				Library:AddToRegistry(BoxOuter, {
					BackgroundColor3 = 'BackgroundColor';
					BorderColor3 = 'OutlineColor';
				});

				local BoxInner = Library:Create('Frame', {
					BackgroundColor3 = Library.BackgroundColor;
					BorderColor3 = Color3.new(0, 0, 0);
					-- BorderMode = Enum.BorderMode.Inset;
					Size = UDim2.new(1, -2, 1, -2);
					Position = UDim2.new(0, 1, 0, 1);
					ZIndex = 4;
					Parent = BoxOuter;
				});

				Library:AddToRegistry(BoxInner, {
					BackgroundColor3 = 'BackgroundColor';
				});

				local Highlight = Library:Create('Frame', {
					BackgroundColor3 = Library.AccentColor;
					BorderSizePixel = 0;
					Size = UDim2.new(1, 0, 0, 2);
					ZIndex = 5;
					Parent = BoxInner;
				});

				Library:AddToRegistry(Highlight, {
					BackgroundColor3 = 'AccentColor';
				});

				local GroupboxLabel = Library:CreateLabel({
					Size = UDim2.new(1, 0, 0, 18);
					Position = UDim2.new(0, 4, 0, 2);
					TextSize = 14;
					Text = Info.Name;
					TextXAlignment = Enum.TextXAlignment.Left;
					ZIndex = 5;
					Parent = BoxInner;
				});

				local Container = Library:Create('Frame', {
					BackgroundTransparency = 1;
					Position = UDim2.new(0, 4, 0, 20);
					Size = UDim2.new(1, -4, 1, -20);
					ZIndex = 1;
					Parent = BoxInner;
				});

				Library:Create('UIListLayout', {
					FillDirection = Enum.FillDirection.Vertical;
					SortOrder = Enum.SortOrder.LayoutOrder;
					Parent = Container;
				});

				function Groupbox:Resize()
					local Size = 0;

					for _, Element in next, Groupbox.Container:GetChildren() do
						if (not Element:IsA('UIListLayout')) and Element.Visible then
							Size = Size + Element.Size.Y.Offset;
						end;
					end;

					BoxOuter.Size = UDim2.new(1, 0, 0, 20 + Size + 2 + 2);
				end;

				Groupbox.Container = Container;
				setmetatable(Groupbox, BaseGroupbox);

				Groupbox:AddBlank(3);
				Groupbox:Resize();

				Tab.Groupboxes[Info.Name] = Groupbox;

				return Groupbox;
			end;

			function Tab:AddLeftGroupbox(Name)
				return Tab:AddGroupbox({ Side = 1; Name = Name; });
			end;

			function Tab:AddRightGroupbox(Name)
				return Tab:AddGroupbox({ Side = 2; Name = Name; });
			end;

			function Tab:AddTabbox(Info)
				local Tabbox = {
					Tabs = {};
				};

				local BoxOuter = Library:Create('Frame', {
					BackgroundColor3 = Library.BackgroundColor;
					BorderColor3 = Library.OutlineColor;
					BorderMode = Enum.BorderMode.Inset;
					Size = UDim2.new(1, 0, 0, 0);
					ZIndex = 2;
					Parent = Info.Side == 1 and LeftSide or RightSide;
				});

				Library:AddToRegistry(BoxOuter, {
					BackgroundColor3 = 'BackgroundColor';
					BorderColor3 = 'OutlineColor';
				});

				local BoxInner = Library:Create('Frame', {
					BackgroundColor3 = Library.BackgroundColor;
					BorderColor3 = Color3.new(0, 0, 0);
					-- BorderMode = Enum.BorderMode.Inset;
					Size = UDim2.new(1, -2, 1, -2);
					Position = UDim2.new(0, 1, 0, 1);
					ZIndex = 4;
					Parent = BoxOuter;
				});

				Library:AddToRegistry(BoxInner, {
					BackgroundColor3 = 'BackgroundColor';
				});

				local Highlight = Library:Create('Frame', {
					BackgroundColor3 = Library.AccentColor;
					BorderSizePixel = 0;
					Size = UDim2.new(1, 0, 0, 2);
					ZIndex = 10;
					Parent = BoxInner;
				});

				Library:AddToRegistry(Highlight, {
					BackgroundColor3 = 'AccentColor';
				});

				local TabboxButtons = Library:Create('Frame', {
					BackgroundTransparency = 1;
					Position = UDim2.new(0, 0, 0, 1);
					Size = UDim2.new(1, 0, 0, 18);
					ZIndex = 5;
					Parent = BoxInner;
				});

				Library:Create('UIListLayout', {
					FillDirection = Enum.FillDirection.Horizontal;
					HorizontalAlignment = Enum.HorizontalAlignment.Left;
					SortOrder = Enum.SortOrder.LayoutOrder;
					Parent = TabboxButtons;
				});

				function Tabbox:AddTab(Name)
					local Tab = {};

					local Button = Library:Create('Frame', {
						BackgroundColor3 = Library.MainColor;
						BorderColor3 = Color3.new(0, 0, 0);
						Size = UDim2.new(0.5, 0, 1, 0);
						ZIndex = 6;
						Parent = TabboxButtons;
					});

					Library:AddToRegistry(Button, {
						BackgroundColor3 = 'MainColor';
					});

					local ButtonLabel = Library:CreateLabel({
						Size = UDim2.new(1, 0, 1, 0);
						TextSize = 14;
						Text = Name;
						TextXAlignment = Enum.TextXAlignment.Center;
						ZIndex = 7;
						Parent = Button;
					});

					local Block = Library:Create('Frame', {
						BackgroundColor3 = Library.BackgroundColor;
						BorderSizePixel = 0;
						Position = UDim2.new(0, 0, 1, 0);
						Size = UDim2.new(1, 0, 0, 1);
						Visible = false;
						ZIndex = 9;
						Parent = Button;
					});

					Library:AddToRegistry(Block, {
						BackgroundColor3 = 'BackgroundColor';
					});

					local Container = Library:Create('Frame', {
						BackgroundTransparency = 1;
						Position = UDim2.new(0, 4, 0, 20);
						Size = UDim2.new(1, -4, 1, -20);
						ZIndex = 1;
						Visible = false;
						Parent = BoxInner;
					});

					Library:Create('UIListLayout', {
						FillDirection = Enum.FillDirection.Vertical;
						SortOrder = Enum.SortOrder.LayoutOrder;
						Parent = Container;
					});

					function Tab:Show()
						for _, Tab in next, Tabbox.Tabs do
							Tab:Hide();
						end;

						Container.Visible = true;
						Block.Visible = true;

						Button.BackgroundColor3 = Library.BackgroundColor;
						Library.RegistryMap[Button].Properties.BackgroundColor3 = 'BackgroundColor';

						Tab:Resize();
					end;

					function Tab:Hide()
						Container.Visible = false;
						Block.Visible = false;

						Button.BackgroundColor3 = Library.MainColor;
						Library.RegistryMap[Button].Properties.BackgroundColor3 = 'MainColor';
					end;

					function Tab:Resize()
						local TabCount = 0;

						for _, Tab in next, Tabbox.Tabs do
							TabCount = TabCount + 1;
						end;

						for _, Button in next, TabboxButtons:GetChildren() do
							if not Button:IsA('UIListLayout') then
								Button.Size = UDim2.new(1 / TabCount, 0, 1, 0);
							end;
						end;

						if (not Container.Visible) then
							return;
						end;

						local Size = 0;

						for _, Element in next, Tab.Container:GetChildren() do
							if (not Element:IsA('UIListLayout')) and Element.Visible then
								Size = Size + Element.Size.Y.Offset;
							end;
						end;

						BoxOuter.Size = UDim2.new(1, 0, 0, 20 + Size + 2 + 2);
					end;

					Button.InputBegan:Connect(function(Input)
						if (Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch) and not Library:MouseIsOverOpenedFrame() then
							Tab:Show();
							Tab:Resize();
						end;
					end);

					Tab.Container = Container;
					Tabbox.Tabs[Name] = Tab;

					setmetatable(Tab, BaseGroupbox);

					Tab:AddBlank(3);
					Tab:Resize();

					-- Show first tab (number is 2 cus of the UIListLayout that also sits in that instance)
					if #TabboxButtons:GetChildren() == 2 then
						Tab:Show();
					end;

					return Tab;
				end;

				Tab.Tabboxes[Info.Name or ''] = Tabbox;

				return Tabbox;
			end;

			function Tab:AddLeftTabbox(Name)
				return Tab:AddTabbox({ Name = Name, Side = 1; });
			end;

			function Tab:AddRightTabbox(Name)
				return Tab:AddTabbox({ Name = Name, Side = 2; });
			end;

			TabButton.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					Tab:ShowTab();
				elseif Input.UserInputType == Enum.UserInputType.Touch then
					-- [PRINCE HUB] باللمس: إذا سحبت الشريط ما يتغير التبويب، بس إذا ضغطت
					local startPos = Input.Position;
					local startCanvas = TabArea.CanvasPosition.X;
					local done = false;
					local conn;
					conn = Input.Changed:Connect(function()
						if done or Input.UserInputState ~= Enum.UserInputState.End then return end;
						done = true;
						if conn then conn:Disconnect() end;
						local moved = 0;
						pcall(function() moved = (Input.Position - startPos).Magnitude end);
						if moved < 12 and math.abs(TabArea.CanvasPosition.X - startCanvas) < 6 then
							Tab:ShowTab();
						end;
					end);
				end;
			end);

			-- This was the first tab added, so we show it by default.
			if #TabContainer:GetChildren() == 1 then
				Tab:ShowTab();
			end;

			Window.Tabs[Name] = Tab;
			return Tab;
		end;

		local ModalElement = Library:Create('TextButton', {
			BackgroundTransparency = 1;
			Size = UDim2.new(0, 0, 0, 0);
			Visible = true;
			Text = '';
			Modal = false;
			Parent = ScreenGui;
		});

		local TransparencyCache = {};
		local Toggled = false;
		local Fading = false;

		function Library:Toggle()
			if Fading then
				return;
			end;

			local FadeTime = Config.MenuFadeTime;
			Fading = true;
			Toggled = (not Toggled);
			ModalElement.Modal = Toggled;

			if Toggled then
				-- A bit scuffed, but if we're going from not toggled -> toggled we want to show the frame immediately so that the fade is visible.
				Outer.Visible = true;

				task.spawn(function()
					-- TODO: add cursor fade?
					local State = InputService.MouseIconEnabled;

					local Cursor = Drawing.new('Triangle');
					Cursor.Thickness = 1;
					Cursor.Filled = true;
					Cursor.Visible = true;

					local CursorOutline = Drawing.new('Triangle');
					CursorOutline.Thickness = 1;
					CursorOutline.Filled = false;
					CursorOutline.Color = Color3.new(0, 0, 0);
					CursorOutline.Visible = true;

					while Toggled and ScreenGui.Parent do
						InputService.MouseIconEnabled = false;

						local mPos = InputService:GetMouseLocation();

						Cursor.Color = Library.AccentColor;

						Cursor.PointA = Vector2.new(mPos.X, mPos.Y);
						Cursor.PointB = Vector2.new(mPos.X + 16, mPos.Y + 6);
						Cursor.PointC = Vector2.new(mPos.X + 6, mPos.Y + 16);

						CursorOutline.PointA = Cursor.PointA;
						CursorOutline.PointB = Cursor.PointB;
						CursorOutline.PointC = Cursor.PointC;

						RenderStepped:Wait();
					end;

					InputService.MouseIconEnabled = State;

					Cursor:Remove();
					CursorOutline:Remove();
				end);
			end;

			for _, Desc in next, Outer:GetDescendants() do
				local Properties = {};

				if Desc:IsA('ImageLabel') then
					table.insert(Properties, 'ImageTransparency');
					table.insert(Properties, 'BackgroundTransparency');
				elseif Desc:IsA('TextLabel') or Desc:IsA('TextBox') then
					table.insert(Properties, 'TextTransparency');
				elseif Desc:IsA('Frame') or Desc:IsA('ScrollingFrame') then
					table.insert(Properties, 'BackgroundTransparency');
				elseif Desc:IsA('UIStroke') then
					table.insert(Properties, 'Transparency');
				end;

				local Cache = TransparencyCache[Desc];

				if (not Cache) then
					Cache = {};
					TransparencyCache[Desc] = Cache;
				end;

				for _, Prop in next, Properties do
					if not Cache[Prop] then
						Cache[Prop] = Desc[Prop];
					end;

					if Cache[Prop] == 1 then
						continue;
					end;

					TweenService:Create(Desc, TweenInfo.new(FadeTime, Enum.EasingStyle.Linear), { [Prop] = Toggled and Cache[Prop] or 1 }):Play();
				end;
			end;

			task.wait(FadeTime);

			Outer.Visible = Toggled;

			Fading = false;
		end

		Library:GiveSignal(InputService.InputBegan:Connect(function(Input, Processed)
			if type(Library.ToggleKeybind) == 'table' and Library.ToggleKeybind.Type == 'KeyPicker' then
				if Input.UserInputType == Enum.UserInputType.Keyboard and Input.KeyCode.Name == Library.ToggleKeybind.Value then
					task.spawn(Library.Toggle)
				end
			elseif Input.KeyCode == Enum.KeyCode.RightControl or (Input.KeyCode == Enum.KeyCode.RightShift and (not Processed)) then
				task.spawn(Library.Toggle)
			end
		end))

		if Config.AutoShow then task.spawn(Library.Toggle) end

		Window.Holder = Outer;

		-- Resize handle (bottom-right corner)
		local resizeHandle = Library:Create('Frame', {
			Size = UDim2.fromOffset(20, 20);
			Position = UDim2.new(1, -20, 1, -20);
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			ZIndex = 20;
			Parent = Outer;
		})
		Library:Create('TextLabel', {
			Size = UDim2.fromScale(1, 1);
			BackgroundTransparency = 1;
			Text = "↘";
			TextColor3 = Color3.fromRGB(255, 105, 180);
			TextSize = 18;
			Font = Enum.Font.GothamBold;
			ZIndex = 21;
			Parent = resizeHandle;
		})

		resizeHandle.InputBegan:Connect(function(input)
			if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
			local startPos = input.Position
			local startSize = Outer.AbsoluteSize
			local startWinPos = Outer.AbsolutePosition
			-- Switch to absolute position to avoid offset caused by AnchorPoint scale
			Outer.AnchorPoint = Vector2.new(0, 0)
			Outer.Position = UDim2.fromOffset(startWinPos.X, startWinPos.Y)
			local conn
			conn = InputService.InputChanged:Connect(function(moved)
				if moved.UserInputType ~= Enum.UserInputType.MouseMovement and moved.UserInputType ~= Enum.UserInputType.Touch then return end
				local delta = moved.Position - startPos
				local newW = math.max(300, (startSize.X + delta.X) / (Library.UIScale or 1)) -- [PRINCE HUB] UIScale
				local newH = math.max(200, (startSize.Y + delta.Y) / (Library.UIScale or 1))
				Outer.Size = UDim2.fromOffset(newW, newH)
			end)
			local endConn
			endConn = InputService.InputEnded:Connect(function(ended)
				if ended.UserInputType == Enum.UserInputType.MouseButton1 or ended.UserInputType == Enum.UserInputType.Touch then
					if conn then conn:Disconnect() end
					if endConn then endConn:Disconnect() end
				end
			end)
		end)

		return Window;
	end;

	local function OnPlayerChange()
		local PlayerList = GetPlayersString();

		for _, Value in next, Options do
			if Value.Type == 'Dropdown' and Value.SpecialType == 'Player' then
				Value:SetValues(PlayerList);
			end;
		end;
	end;

	Players.PlayerAdded:Connect(OnPlayerChange);
	Players.PlayerRemoving:Connect(OnPlayerChange);

	getgenv().Library = Library
	return Library
end)()

local ThemeManager = (function()
	local httpService = game:GetService('HttpService')
	local ThemeManager = {} do
		ThemeManager.Folder = 'LinoriaLibSettings'
		-- if not isfolder(ThemeManager.Folder) then makefolder(ThemeManager.Folder) end

		ThemeManager.Library = nil
		ThemeManager.DefaultTheme = 'Default'
		ThemeManager.BuiltInThemes = {
			['Default'] = { 1, httpService:JSONDecode('{"FontColor":"e9edfa","MainColor":"24273a","AccentColor":"f5bde6","BackgroundColor":"1e2030","OutlineColor":"363a4f"}') },
		}

		function ThemeManager:ApplyTheme(theme)
			local customThemeData = self:GetCustomTheme(theme)
			local data = customThemeData or self.BuiltInThemes[theme]

			if not data then return end

			-- custom themes are just regular dictionaries instead of an array with { index, dictionary }

			local scheme = data[2]
			for idx, col in next, customThemeData or scheme do
				self.Library[idx] = Color3.fromHex(col)

				if Options[idx] then
					Options[idx]:SetValueRGB(Color3.fromHex(col))
				end
			end

			self:ThemeUpdate()
		end

		function ThemeManager:ThemeUpdate()
			-- This allows us to force apply themes without loading the themes tab :)
			local options = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" }
			for i, field in next, options do
				if Options and Options[field] then
					self.Library[field] = Options[field].Value
				end
			end

			self.Library.AccentColorDark = self.Library:GetDarkerColor(self.Library.AccentColor);
			self.Library:UpdateColorsUsingRegistry()
		end

		function ThemeManager:LoadDefault()
			-- Always apply the only theme that exists
			self:ApplyTheme('Default')
		end

		function ThemeManager:SaveDefault(theme)
			writefile(self.Folder .. '/themes/default.txt', theme)
		end

		function ThemeManager:CreateThemeManager(groupbox)
			-- No UI: only the Default theme exists and is hardcoded
			ThemeManager:LoadDefault()
		end

		function ThemeManager:GetCustomTheme(file)
			local path = self.Folder .. '/themes/' .. file
			if not isfile(path) then
				return nil
			end

			local data = readfile(path)
			local success, decoded = pcall(httpService.JSONDecode, httpService, data)

			if not success then
				return nil
			end

			return decoded
		end

		function ThemeManager:SaveCustomTheme(file)
			if file:gsub(' ', '') == '' then
				return self.Library:Notify('Invalid file name for theme (empty)', 3)
			end

			local theme = {}
			local fields = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" }

			for _, field in next, fields do
				theme[field] = Options[field].Value:ToHex()
			end

			writefile(self.Folder .. '/themes/' .. file .. '.json', httpService:JSONEncode(theme))
		end

		function ThemeManager:ReloadCustomThemes()
			local list = listfiles(self.Folder .. '/themes')

			local out = {}
			for i = 1, #list do
				local file = list[i]
				if file:sub(-5) == '.json' then
					-- i hate this but it has to be done ...

					local pos = file:find('.json', 1, true)
					local char = file:sub(pos, pos)

					while char ~= '/' and char ~= '\\' and char ~= '' do
						pos = pos - 1
						char = file:sub(pos, pos)
					end

					if char == '/' or char == '\\' then
						table.insert(out, file:sub(pos + 1))
					end
				end
			end

			return out
		end

		function ThemeManager:SetLibrary(lib)
			self.Library = lib
		end

		function ThemeManager:BuildFolderTree()
			local paths = {}

			-- build the entire tree if a path is like some-hub/phantom-forces
			-- makefolder builds the entire tree on Synapse X but not other exploits

			local parts = self.Folder:split('/')
			for idx = 1, #parts do
				paths[#paths + 1] = table.concat(parts, '/', 1, idx)
			end

			table.insert(paths, self.Folder .. '/themes')
			table.insert(paths, self.Folder .. '/settings')

			for i = 1, #paths do
				local str = paths[i]
				if not isfolder(str) then
					makefolder(str)
				end
			end
		end

		function ThemeManager:SetFolder(folder)
			self.Folder = folder
			self:BuildFolderTree()
		end

		function ThemeManager:CreateGroupBox(tab)
			assert(self.Library, 'Must set ThemeManager.Library first!')
			return tab:AddLeftGroupbox('Themes')
		end

		function ThemeManager:ApplyToTab(tab)
			assert(self.Library, 'Must set ThemeManager.Library first!')
			local groupbox = self:CreateGroupBox(tab)
			self:CreateThemeManager(groupbox)
		end

		function ThemeManager:ApplyToGroupbox(groupbox)
			assert(self.Library, 'Must set ThemeManager.Library first!')
			self:CreateThemeManager(groupbox)
		end

		ThemeManager:BuildFolderTree()
	end

	return ThemeManager
end)()

local SaveManager = (function()
	local httpService = game:GetService('HttpService')

	local SaveManager = {} do
		SaveManager.Folder = 'LinoriaLibSettings'
		SaveManager.Ignore = {}
		SaveManager.Parser = {
			Toggle = {
				Save = function(idx, object) 
					return { type = 'Toggle', idx = idx, value = object.Value } 
				end,
				Load = function(idx, data)
					if Toggles[idx] then 
						Toggles[idx]:SetValue(data.value)
					end
				end,
			},
			Slider = {
				Save = function(idx, object)
					return { type = 'Slider', idx = idx, value = tostring(object.Value) }
				end,
				Load = function(idx, data)
					if Options[idx] then 
						Options[idx]:SetValue(data.value)
					end
				end,
			},
			Dropdown = {
				Save = function(idx, object)
					return { type = 'Dropdown', idx = idx, value = object.Value, mutli = object.Multi }
				end,
				Load = function(idx, data)
					if Options[idx] then 
						Options[idx]:SetValue(data.value)
					end
				end,
			},
			ColorPicker = {
				Save = function(idx, object)
					return { type = 'ColorPicker', idx = idx, value = object.Value:ToHex(), transparency = object.Transparency }
				end,
				Load = function(idx, data)
					if Options[idx] then 
						Options[idx]:SetValueRGB(Color3.fromHex(data.value), data.transparency)
					end
				end,
			},
			KeyPicker = {
				Save = function(idx, object)
					return { type = 'KeyPicker', idx = idx, mode = object.Mode, key = object.Value }
				end,
				Load = function(idx, data)
					if Options[idx] then 
						Options[idx]:SetValue({ data.key, data.mode })
					end
				end,
			},

			Input = {
				Save = function(idx, object)
					return { type = 'Input', idx = idx, text = object.Value }
				end,
				Load = function(idx, data)
					if Options[idx] and type(data.text) == 'string' then
						Options[idx]:SetValue(data.text)
					end
				end,
			},
		}

		function SaveManager:SetIgnoreIndexes(list)
			for _, key in next, list do
				self.Ignore[key] = true
			end
		end

		function SaveManager:SetFolder(folder)
			self.Folder = folder;
			self:BuildFolderTree()
		end

		function SaveManager:Save(name)
			if (not name) then
				return false, 'no config file is selected'
			end

			local fullPath = self.Folder .. '/settings/' .. name .. '.json'

			local data = {
				objects = {}
			}

			for idx, toggle in next, Toggles do
				if self.Ignore[idx] then continue end

				table.insert(data.objects, self.Parser[toggle.Type].Save(idx, toggle))
			end

			for idx, option in next, Options do
				if not self.Parser[option.Type] then continue end
				if self.Ignore[idx] then continue end

				table.insert(data.objects, self.Parser[option.Type].Save(idx, option))
			end	

			local success, encoded = pcall(httpService.JSONEncode, httpService, data)
			if not success then
				return false, 'failed to encode data'
			end

			writefile(fullPath, encoded)
			return true
		end

		function SaveManager:Load(name)
			if (not name) then
				return false, 'no config file is selected'
			end

			local file = self.Folder .. '/settings/' .. name .. '.json'
			if not isfile(file) then return false, 'invalid file' end

			local success, decoded = pcall(httpService.JSONDecode, httpService, readfile(file))
			if not success then return false, 'decode error' end

			for _, option in next, decoded.objects do
				if self.Parser[option.type] then
					task.spawn(function() self.Parser[option.type].Load(option.idx, option) end) -- task.spawn() so the config loading wont get stuck.
				end
			end

			return true
		end

		function SaveManager:IgnoreThemeSettings()
			self:SetIgnoreIndexes({ 
				"BackgroundColor", "MainColor", "AccentColor", "OutlineColor", "FontColor", -- themes
				"ThemeManager_ThemeList", 'ThemeManager_CustomThemeList', 'ThemeManager_CustomThemeName', -- themes
			})
		end

		function SaveManager:BuildFolderTree()
			local paths = {
				self.Folder,
				self.Folder .. '/themes',
				self.Folder .. '/settings'
			}

			for i = 1, #paths do
				local str = paths[i]
				if not isfolder(str) then
					makefolder(str)
				end
			end
		end

		function SaveManager:RefreshConfigList()
			local list = listfiles(self.Folder .. '/settings')

			local out = {}
			for i = 1, #list do
				local file = list[i]
				if file:sub(-5) == '.json' then
					-- i hate this but it has to be done ...

					local pos = file:find('.json', 1, true)
					local start = pos

					local char = file:sub(pos, pos)
					while char ~= '/' and char ~= '\\' and char ~= '' do
						pos = pos - 1
						char = file:sub(pos, pos)
					end

					if char == '/' or char == '\\' then
						table.insert(out, file:sub(pos + 1, start - 1))
					end
				end
			end

			return out
		end

		function SaveManager:SetLibrary(library)
			self.Library = library
		end

		function SaveManager:LoadAutoloadConfig()
			if isfile(self.Folder .. '/settings/autoload.txt') then
				local name = readfile(self.Folder .. '/settings/autoload.txt')

				local success, err = self:Load(name)
				if not success then
					return self.Library:Notify('Failed to load autoload config: ' .. err)
				end

				self.Library:Notify(string.format('Auto loaded config %q', name))
			end
		end


		function SaveManager:BuildConfigSection(tab)
			assert(self.Library, 'Must set SaveManager.Library')

			local section = tab:AddRightGroupbox('Configuration')

			section:AddInput('SaveManager_ConfigName',    { Text = 'Config name' })
			section:AddDropdown('SaveManager_ConfigList', { Text = 'Config list', Values = self:RefreshConfigList(), AllowNull = true })

			section:AddDivider()

			section:AddButton('Create config', function()
				local name = Options.SaveManager_ConfigName.Value

				if name:gsub(' ', '') == '' then 
					return self.Library:Notify('Invalid config name (empty)', 2)
				end

				local success, err = self:Save(name)
				if not success then
					return self.Library:Notify('Failed to save config: ' .. err)
				end

				self.Library:Notify(string.format('Created config %q', name))

				Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
				Options.SaveManager_ConfigList:SetValue(nil)
			end):AddButton('Load config', function()
				local name = Options.SaveManager_ConfigList.Value

				local success, err = self:Load(name)
				if not success then
					return self.Library:Notify('Failed to load config: ' .. err)
				end

				self.Library:Notify(string.format('Loaded config %q', name))
			end)

			section:AddButton('Overwrite config', function()
				local name = Options.SaveManager_ConfigList.Value

				local success, err = self:Save(name)
				if not success then
					return self.Library:Notify('Failed to overwrite config: ' .. err)
				end

				self.Library:Notify(string.format('Overwrote config %q', name))
			end)

			section:AddButton('Refresh list', function()
				Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
				Options.SaveManager_ConfigList:SetValue(nil)
			end)

			section:AddButton('Set as autoload', function()
				local name = Options.SaveManager_ConfigList.Value
				writefile(self.Folder .. '/settings/autoload.txt', name)
				SaveManager.AutoloadLabel:SetText('Current autoload config: ' .. name)
				self.Library:Notify(string.format('Set %q to auto load', name))
			end)

			SaveManager.AutoloadLabel = section:AddLabel('Current autoload config: none', true)

			if isfile(self.Folder .. '/settings/autoload.txt') then
				local name = readfile(self.Folder .. '/settings/autoload.txt')
				SaveManager.AutoloadLabel:SetText('Current autoload config: ' .. name)
			end

			SaveManager:SetIgnoreIndexes({ 'SaveManager_ConfigList', 'SaveManager_ConfigName' })
		end

		SaveManager:BuildFolderTree()
	end

	return SaveManager

end)()


