_G_Hub.DoArcTeleport = function(targetPos)
	local H = _G_Hub
	if typeof(targetPos) == "CFrame" then targetPos = targetPos.Position end

	local char = H.lp.Character
	local rp = char and char:FindFirstChild("HumanoidRootPart")
	local hum = char and char:FindFirstChild("Humanoid")
	if not rp or not hum or hum.Health <= 0 then return end


	rp = H.lp.Character and H.lp.Character:FindFirstChild("HumanoidRootPart")
	if not rp then return end

	local dist = (rp.Position - targetPos).Magnitude
	if dist < 5 then
		rp.CFrame = (rp.CFrame - rp.Position) + targetPos
		return
	end

	if H.activeTpConn then H.activeTpConn:Disconnect(); H.activeTpConn = nil end
	if H.invisibleFloor then H.invisibleFloor:Destroy(); H.invisibleFloor = nil end
	-- Supprimer tous les BodyVelocity farm pour que le tween puisse bouger librement
	for _, bvName in ipairs({"AF_BV", "S2_BV", "AH_BV"}) do
		local bv = rp:FindFirstChild(bvName)
		if bv then bv:Destroy() end
	end


	H.isTeleporting = true
	H.tpTarget = targetPos
	H.tpId = (H.tpId or 0) + 1
	local currentTpId = H.tpId

	local speed = H.teleportSpeed or 89
	local reached = false

	-- always forces high arc mode
	local safeAlt = math.max(rp.Position.Y, targetPos.Y) + 2500
	local waypoints = {
		Vector3.new(rp.Position.X, safeAlt, rp.Position.Z),
		Vector3.new(targetPos.X, safeAlt, targetPos.Z),
	}
	-- Intermediate waypoint if target is very low (e.g. Fishman cave)
	if targetPos.Y < -500 then
		table.insert(waypoints, Vector3.new(targetPos.X, (safeAlt + targetPos.Y) / 2, targetPos.Z))
	end
	table.insert(waypoints, targetPos)

	local currentWp = 1

	local invisibleFloor = Instance.new("Part")
	invisibleFloor.Size = Vector3.new(10, 1, 10)
	invisibleFloor.Transparency = 1
	invisibleFloor.Anchored = true
	invisibleFloor.CanCollide = true
	invisibleFloor.Parent = workspace
	H.invisibleFloor = invisibleFloor

	if not H.DisableForwardKey then
		H.VIM:SendKeyEvent(true, Enum.KeyCode.W, false, game)
	end
	playTweenAnim()

	task.spawn(function()
		local API = H.ReplicatedStorage and H.ReplicatedStorage:FindFirstChild("Events")
		local faceMouseRemote = API and API:FindFirstChild("faceMouse")
		while not reached and H.tpId == currentTpId do
			if faceMouseRemote then
				pcall(function() faceMouseRemote:FireServer(true) end)
				pcall(function() faceMouseRemote:FireServer(false) end)
			end
			task.wait(1)
		end
		if H.tpId == currentTpId then
			H.VIM:SendKeyEvent(false, Enum.KeyCode.W, false, game)
		end
	end)

	local conn
	conn = H.run_svc.Heartbeat:Connect(function(dt)
		if not rp or not rp.Parent or hum.Health <= 0 or H.tpId ~= currentTpId then
			reached = true
			if conn then conn:Disconnect() end
			return
		end
		local wp = waypoints[currentWp]
		local d = (rp.Position - wp).Magnitude
		if d <= 20 then
			-- Snap direct au waypoint
			rp.CFrame = (rp.CFrame - rp.Position) + wp
			rp.AssemblyLinearVelocity = Vector3.zero
			currentWp = currentWp + 1
			if currentWp > #waypoints then
				rp.CFrame = (rp.CFrame - rp.Position) + targetPos
				rp.AssemblyLinearVelocity = Vector3.zero
				reached = true
				if H.invisibleFloor then H.invisibleFloor:Destroy(); H.invisibleFloor = nil end
				H.isTeleporting = false
				stopTweenAnim()
				if conn then conn:Disconnect() end
				return
			end
			wp = waypoints[currentWp]
			d = (rp.Position - wp).Magnitude
		end
		local dir = (wp - rp.Position).Unit
		local moveStep = math.min(speed * dt, d * 0.9)
		rp.CFrame = (rp.CFrame - rp.Position) + (rp.Position + dir * moveStep)
		rp.AssemblyLinearVelocity = Vector3.zero
		if H.invisibleFloor and H.invisibleFloor.Parent then
			H.invisibleFloor.CFrame = rp.CFrame * CFrame.new(0, -3.1, 0)
		end
	end)
	H.activeTpConn = conn

	while not reached and H.tpId == currentTpId do
		task.wait(0.1)
	end
end

-- ============================================================
-- FEATURE: GROUND WALK
-- ============================================================
_G_Hub.DoGroundWalk = function(targetPos)
	local H = _G_Hub
	if typeof(targetPos) == "CFrame" then targetPos = targetPos.Position end

	local char = H.lp.Character
	local rp   = char and char:FindFirstChild("HumanoidRootPart")
	local hum  = char and char:FindFirstChild("Humanoid")
	if not rp or not hum or hum.Health <= 0 then return end

	local dist = (rp.Position - targetPos).Magnitude
	if dist < 5 then
		rp.CFrame = (rp.CFrame - rp.Position) + targetPos
		return
	end

	if H.activeTpConn then H.activeTpConn:Disconnect(); H.activeTpConn = nil end

	H.isTeleporting = true
	H.tpId = (H.tpId or 0) + 1
	local currentTpId = H.tpId

	local speed   = H.teleportSpeed or 89
	local reached = false
	local fixedY = rp.Position.Y

	local conn
	conn = H.run_svc.Heartbeat:Connect(function(dt)
		if not rp or not rp.Parent or hum.Health <= 0 or H.tpId ~= currentTpId then
			reached = true
			if conn then conn:Disconnect() end
			return
		end

		local flatTarget = Vector3.new(targetPos.X, fixedY, targetPos.Z)
		local d = (rp.Position - flatTarget).Magnitude

		if d <= 8 then
			rp.CFrame = (rp.CFrame - rp.Position) + targetPos
			rp.AssemblyLinearVelocity = Vector3.zero
			reached = true
			H.isTeleporting = false
			if conn then conn:Disconnect() end
			return
		end

		local dir      = (flatTarget - rp.Position).Unit
		local moveStep = math.min(speed * dt, d * 0.98)
		rp.CFrame = (rp.CFrame - rp.Position) + (rp.Position + dir * moveStep)
		rp.AssemblyLinearVelocity = Vector3.zero
	end)
	H.activeTpConn = conn

	while not reached and H.tpId == currentTpId do
		task.wait(0.1)
	end
end

-- ============================================================
-- [PRINCE HUB] KAITUN NEW FLIGHT  (Auto Farm Sea 1 / Sea 2)
-- طيران الكايتون الجديد منسوخ حرفياً من MODULE: Kaitun (بحالة خاصة بيه).
-- H.DoSafeTeleport القديم باقي لباقي الميزات (صيد، تاجر، هاكي، جزر...).
-- ============================================================
_G_Hub.KaitunFlight = (function()
	local Players           = game:GetService("Players")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local RunService        = game:GetService("RunService")
	local VirtualInput      = game:GetService("VirtualInputManager")
	local LocalPlayer       = Players.LocalPlayer

	local H = {
		teleportSpeed = 70,
		tpToken = 0,
		noclipActive = false,
		noclipConn = nil,
		lastNoclipTakeStam = 0,
		fishmanEscaping = false,
	}

	local function getCharacter()
		local char = LocalPlayer.Character
		if char and char:FindFirstChild("HumanoidRootPart") and char:FindFirstChildOfClass("Humanoid") then
			return char
		end
		local pc = workspace:FindFirstChild("PlayerCharacters")
		local folderChar = pc and pc:FindFirstChild(LocalPlayer.Name)
		if folderChar and folderChar:FindFirstChild("HumanoidRootPart") and folderChar:FindFirstChildOfClass("Humanoid") then
			return folderChar
		end
		return char or folderChar
	end
	local function getHRP()
		local char = getCharacter()
		return char and char:FindFirstChild("HumanoidRootPart")
	end
	local function getHumanoid()
		local char = getCharacter()
		return char and char:FindFirstChildOfClass("Humanoid")
	end

	local fireTakeStamDash = function() end
	local releaseMovementKeys = function() end

	local function isFishmanRegionPosition(pos)
		if typeof(pos) ~= "Vector3" then return false end
		-- Fishman cave/island lives very deep under the map around X 7k-8.8k,
		-- Z -17k. Keep this broad so respawn/knockback spots are still detected.
		return pos.Y < -1000
			and pos.X >= 6500 and pos.X <= 9300
			and pos.Z >= -18250 and pos.Z <= -14500
	end

	local function setNoclip(state)
		H.noclipActive = state == true
		if H.noclipActive and not H.noclipConn then
			local cachedChar = nil
			local cachedParts = {}
			local lastCacheTime = 0
			H.noclipConn = RunService.Stepped:Connect(function()
				if not H.noclipActive then return end
				local char = getCharacter()
				if not char then return end
				local now = tick()
				if char ~= cachedChar or now - lastCacheTime >= 2 then
					cachedChar = char
					cachedParts = {}
					lastCacheTime = now
					for _, obj in ipairs(char:GetDescendants()) do
						if obj:IsA("BasePart") then
							table.insert(cachedParts, obj)
						end
					end
				end
				for _, obj in ipairs(cachedParts) do
					if obj and obj.Parent then obj.CanCollide = false end
				end
				if now - (H.lastNoclipTakeStam or 0) >= 0.30 then
					H.lastNoclipTakeStam = now
					fireTakeStamDash()
				end
			end)
		elseif not H.noclipActive and H.noclipConn then
			H.noclipConn:Disconnect()
			H.noclipConn = nil
		end
	end

	releaseMovementKeys = function()
		pcall(function()
			for _, key in ipairs({
				Enum.KeyCode.W, Enum.KeyCode.A, Enum.KeyCode.S, Enum.KeyCode.D,
				Enum.KeyCode.Z, Enum.KeyCode.Q,
				Enum.KeyCode.Up, Enum.KeyCode.Down, Enum.KeyCode.Left, Enum.KeyCode.Right,
				}) do
				VirtualInput:SendKeyEvent(false, key, false, game)
			end
		end)
		local hum = getHumanoid()
		local rp = getHRP()
		if hum then
			hum:Move(Vector3.zero, false)
			hum.PlatformStand = false
			hum.Sit = false
			hum.AutoRotate = true
		end
		if rp then
			local bv = rp:FindFirstChild("KT_AirHoldBV")
			if bv then bv:Destroy() end
			local bp = rp:FindFirstChild("KT_AirHoldBP")
			if bp then bp:Destroy() end
			local diveBv = rp:FindFirstChild("KT_WaterDiveBV")
			if diveBv then diveBv:Destroy() end
			rp.AssemblyLinearVelocity = Vector3.zero
			rp.AssemblyAngularVelocity = Vector3.zero
		end
		if hum then
			pcall(function()
				hum:SetStateEnabled(Enum.HumanoidStateType.Swimming, true)
			end)
		end
	end

	fireTakeStamDash = function()
		local events = ReplicatedStorage:FindFirstChild("Events")
		local takestam = events and events:FindFirstChild("takestam")
		local rp = getHRP()
		if not takestam or not rp then return end
		pcall(function()
			takestam:FireServer(1, "dash", rp.CFrame)
		end)
	end

	local function fireFaceMouse()
		if H.fishmanEscaping then return end
		local rp = getHRP()
		if rp and isFishmanRegionPosition(rp.Position) then return end
		local events = ReplicatedStorage:FindFirstChild("Events")
		local faceMouse = events and events:FindFirstChild("faceMouse")
		if not faceMouse then return end
		pcall(function()
			faceMouse:FireServer(true)
			faceMouse:FireServer(false)
		end)
	end

	local function shouldUseTravelFaceMouse(startPos, targetPos, noArc)
		if H.fishmanEscaping then
			return false
		end
		if isFishmanRegionPosition(startPos) then
			return false
		end
		if typeof(startPos) ~= "Vector3" or typeof(targetPos) ~= "Vector3" then
			return false
		end
		local dist = (startPos - targetPos).Magnitude
		local yDiff = math.abs(startPos.Y - targetPos.Y)
		return dist >= 400 or yDiff >= 80 or not noArc
	end

	local function shouldUseTravelArc(startPos, targetPos, noArc)
		if typeof(startPos) ~= "Vector3" or typeof(targetPos) ~= "Vector3" then
			return false
		end
		local dist = (startPos - targetPos).Magnitude
		if dist < 300 then
			return false
		end
		if not noArc then
			return true
		end
		return dist >= 1000 or startPos.Y < -500 or targetPos.Y < -500
	end

	local function setWaterDiveAssist(rp, hum, enabled, targetY)
		if not rp then return end
		local diveBv = rp:FindFirstChild("KT_WaterDiveBV")
		if enabled then
			if hum then
				pcall(function()
					hum:SetStateEnabled(Enum.HumanoidStateType.Swimming, false)
				end)
				pcall(function()
					hum:ChangeState(Enum.HumanoidStateType.Freefall)
				end)
			end
			if not diveBv then
				diveBv = Instance.new("BodyVelocity")
				diveBv.Name = "KT_WaterDiveBV"
				diveBv.Parent = rp
			end
			diveBv.MaxForce = Vector3.new(0, 1e9, 0)
			diveBv.P = 1e7
			diveBv.Velocity = Vector3.new(0, -math.clamp(math.abs(rp.Position.Y - (targetY or rp.Position.Y)) + 20, 35, 140), 0)
		else
			if diveBv then diveBv:Destroy() end
			if hum then
				pcall(function()
					hum:SetStateEnabled(Enum.HumanoidStateType.Swimming, true)
				end)
			end
		end
	end

	local function DoSafeTeleport(targetPos, noArc, allowNoclip)
		if typeof(targetPos) == "CFrame" then targetPos = targetPos.Position end
		if typeof(targetPos) ~= "Vector3" then return end
		local rp = getHRP()
		local hum = getHumanoid()
		if not rp or not hum or hum.Health <= 0 then return end
		H.tpToken = H.tpToken + 1
		local myToken = H.tpToken
		local startPos = rp.Position
		local dist = (startPos - targetPos).Magnitude
		local useTravelFaceMouse = shouldUseTravelFaceMouse(startPos, targetPos, noArc)
		local useTravelArc = shouldUseTravelArc(startPos, targetPos, noArc)
		local holdForwardKey = useTravelFaceMouse or useTravelArc
		if allowNoclip == false then
			setNoclip(false)
		else
			setNoclip(true)
		end
		releaseMovementKeys()
		if holdForwardKey then
			pcall(function()
				VirtualInput:SendKeyEvent(true, Enum.KeyCode.W, false, game)
			end)
		end
		local route = {}
		if useTravelArc then
			local safeAlt = math.max(startPos.Y, targetPos.Y) + 2500
			table.insert(route, Vector3.new(startPos.X, safeAlt, startPos.Z))
			table.insert(route, Vector3.new(targetPos.X, safeAlt, targetPos.Z))
			if targetPos.Y < -500 then
				table.insert(route, Vector3.new(targetPos.X, (safeAlt + targetPos.Y) / 2, targetPos.Z))
			end
		end
		table.insert(route, targetPos)
		local floor = Instance.new("Part")
		floor.Name = "KaitunInvisibleFloor"
		floor.Size = Vector3.new(10, 1, 10)
		floor.Transparency = 1
		floor.Anchored = true
		floor.CanCollide = true
		floor.Parent = workspace
		local moving = true
		task.spawn(function()
			local lastFaceMouse = 0
			while moving and H.tpToken == myToken do
				fireTakeStamDash()
				if useTravelFaceMouse and tick() - lastFaceMouse >= 0.10 then
					lastFaceMouse = tick()
					fireFaceMouse()
				end
				task.wait(0.08)
			end
		end)
		for wpIndex, wp in ipairs(route) do
			if useTravelFaceMouse then
				fireFaceMouse()
			end
			while H.tpToken == myToken do
				rp = getHRP()
				hum = getHumanoid()
				if not rp or not hum or hum.Health <= 0 then break end
				local currentDist = (rp.Position - wp).Magnitude
				local isLastWaypoint = wpIndex == #route
				local reachDistance = isLastWaypoint and 2.5 or 15
				local shouldDiveNow = isLastWaypoint and wp.Y < (rp.Position.Y - 4) and (targetPos.Y < 25 or rp.Position.Y < 25)
				setWaterDiveAssist(rp, hum, shouldDiveNow, wp.Y)
				if currentDist <= reachDistance then
					setWaterDiveAssist(rp, hum, false, wp.Y)
					rp.AssemblyLinearVelocity = Vector3.zero
					rp.AssemblyAngularVelocity = Vector3.zero
					break
				end
				local dt = RunService.Heartbeat:Wait()
				local dir = (wp - rp.Position).Unit
				local step = math.min((H.teleportSpeed or 70) * dt, currentDist)
				if useTravelFaceMouse then
					fireFaceMouse()
				end
				rp.CFrame = (rp.CFrame - rp.Position) + (rp.Position + dir * step)
				rp.AssemblyLinearVelocity = Vector3.zero
				rp.AssemblyAngularVelocity = Vector3.zero
				if floor and floor.Parent then
					floor.CFrame = rp.CFrame * CFrame.new(0, -3.1, 0)
				end
			end
		end
		moving = false
		if floor then floor:Destroy() end
		pcall(function()
			local endRp = getHRP()
			local endHum = getHumanoid()
			if endRp then
				setWaterDiveAssist(endRp, endHum, false, targetPos.Y)
			end
		end)
		releaseMovementKeys()
	end

	local KF = {}

	-- بدال H.DoSafeTeleport / H.DoGroundWalk بالفارم:
	--   noArc = nil  -> نفس سفر الكايتون (قوس عالي إذا 300+ stud)
	--   noArc = true -> نفس نقاط الكايتون (مباشر، قوس بس إذا 1000+)
	--   stillOn()    -> إذا رجّع false (الفارم انطفى) يوقف الطيران
	--   endNoclip    -> للميزات العادية (مو فارم): يطفي noclip الكايتون بعد الوصول
	function KF.teleport(targetPos, noArc, stillOn, endNoclip)
		local Hub = _G_Hub
		if typeof(targetPos) == "CFrame" then targetPos = targetPos.Position end
		if typeof(targetPos) ~= "Vector3" then return end
		local rp = getHRP()
		local hum = getHumanoid()
		if not rp or not hum or hum.Health <= 0 then return end

		-- نفس تحضير tween الهب: يوقف أي tween قديم ويشيل BodyVelocity مال الفارم
		if Hub.activeTpConn then Hub.activeTpConn:Disconnect(); Hub.activeTpConn = nil end
		if Hub.invisibleFloor then Hub.invisibleFloor:Destroy(); Hub.invisibleFloor = nil end
		for _, bvName in ipairs({ "AF_BV", "S2_BV", "AH_BV", "KT_AirHoldBV", "KT_AirHoldBP" }) do
			local bv = rp:FindFirstChild(bvName)
			if bv then bv:Destroy() end
		end

		Hub.isTeleporting = true
		Hub.tpTarget = targetPos
		Hub.tpId = (Hub.tpId or 0) + 1
		local myId = Hub.tpId
		H.teleportSpeed = tonumber(Hub.teleportSpeed) or 70

		-- أي كود بالهب يسوي H.activeTpConn:Disconnect() (مثل stop) يوقف طيران الكايتون
		local handle = { Connected = true }
		function handle:Disconnect()
			if self.Connected then
				self.Connected = false
				H.tpToken = H.tpToken + 1
			end
		end
		Hub.activeTpConn = handle

		local flying = true
		task.spawn(function()
			while flying do
				task.wait(0.1)
				if not flying then break end
				if Hub.tpId ~= myId or (stillOn and not stillOn()) then
					H.tpToken = H.tpToken + 1
					break
				end
				H.teleportSpeed = tonumber(Hub.teleportSpeed) or H.teleportSpeed
			end
		end)

		DoSafeTeleport(targetPos, noArc, true)
		flying = false
		handle.Connected = false
		if Hub.activeTpConn == handle then Hub.activeTpConn = nil end
		if Hub.tpId == myId then
			Hub.isTeleporting = false
			if endNoclip then
				pcall(setNoclip, false)
			end
		end
	end

	KF.setNoclip = setNoclip
	KF.releaseMovementKeys = releaseMovementKeys

	-- لما الفارم يوقف: يوقف الطيران ويطفي noclip الكايتون
	function KF.stop()
		H.tpToken = H.tpToken + 1
		pcall(setNoclip, false)
		pcall(releaseMovementKeys)
	end

	return KF
end)()

-- ============================================================
-- [PRINCE HUB] KAITUN COMBAT: نظام القتال مال Kaitun new (منسوخ حرفياً من MODULE: Kaitun)
-- يستخدمه Auto Farm Sea 1 و Auto Farm Sea 2:
--   equipMelee (EquipTool) / air hold فوق الموب (BodyVelocity + BodyPosition)
--   doDamageCombo (5 ضربات، يلحگ أقرب موب ويضرب كل الموبات القريبة)
--   hitSingleNPC / takeQuest (يلغي الكويست الغلط) / attackWolf (سي 2) / طريق كهف الفيشمان
-- ============================================================
_G_Hub.KaitunCombat = (function()
	local Players           = game:GetService("Players")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local RunService        = game:GetService("RunService")
	local LocalPlayer       = Players.LocalPlayer
	local KF                = _G_Hub.KaitunFlight

	-- نفس قيم الكايتون (H.YETI_*)
	local H = {
		YETI_HIT_DISTANCE = 0,
		YETI_HIT_ROTATION_X = 0,
		YETI_HIT_ROTATION_Y = 0,
		YETI_HIT_ROTATION_Z = 0,
		YETI_HOVER_HEIGHT = 8.3,
	}
	local KC_ON = function() return true end
	local KC_TARGET = "Crazy Wolf"
	local S2 = { upHeight = 9, canAttack = true }

	local function notify() end -- الكايتون صامت
	local function setNoclip(state) pcall(KF.setNoclip, state) end
	local function releaseMovementKeys() pcall(KF.releaseMovementKeys) end

	local function getCharacter()
		local char = LocalPlayer.Character
		if char and char:FindFirstChild("HumanoidRootPart") and char:FindFirstChildOfClass("Humanoid") then
			return char
		end
		local pc = workspace:FindFirstChild("PlayerCharacters")
		local folderChar = pc and pc:FindFirstChild(LocalPlayer.Name)
		if folderChar and folderChar:FindFirstChild("HumanoidRootPart") and folderChar:FindFirstChildOfClass("Humanoid") then
			return folderChar
		end
		return char or folderChar
	end

	local function getHRP()
		local char = getCharacter()
		return char and char:FindFirstChild("HumanoidRootPart")
	end

	local function getHumanoid()
		local char = getCharacter()
		return char and char:FindFirstChildOfClass("Humanoid")
	end

	local function getStatsRoot()
		return ReplicatedStorage:FindFirstChild("Stats" .. LocalPlayer.Name)
	end

	local function getQuest()
		local root = getStatsRoot()
		local cq = root and root:FindFirstChild("Quest") and root.Quest:FindFirstChild("CurrentQuest")
		return cq and cq.Value or ""
	end

	local combatRegister = ReplicatedStorage:WaitForChild("Events"):WaitForChild("CombatRegister")
	local questEvent = ReplicatedStorage:WaitForChild("Events"):WaitForChild("Quest")
	local combatAnimations = ReplicatedStorage:WaitForChild("CombatAnimations"):WaitForChild("Melee")
	local CombatAnims = {
		[1] = combatAnimations.Punch1,
		[2] = combatAnimations.Punch2,
		[3] = combatAnimations.Punch3,
		[4] = combatAnimations.GroundPunch4,
		[5] = combatAnimations.GroundPunch5,
	}

	local function equipMelee()
		local backpack = LocalPlayer:FindFirstChild("Backpack")
		local char = getCharacter()
		if not backpack or not char then return false end
		if char:FindFirstChild("Melee") then return true end
		local melee = backpack:FindFirstChild("Melee")
		if not melee then return false end
		local hum = char:FindFirstChildOfClass("Humanoid")
		if hum then
			pcall(function() hum:EquipTool(melee) end)
		else
			melee.Parent = char
		end
		task.wait(0.2)
		return char:FindFirstChild("Melee") ~= nil
	end

	local function getNPCID(npc)
		if not npc then return nil end
		local v = npc:FindFirstChild("NPCID")
		if v then return v.Value end
		local cfg = npc:FindFirstChild("Configuration")
		if cfg then
			local cv = cfg:FindFirstChild("NPCID")
			if cv then return cv.Value end
		end
		return npc:GetAttribute("NPCID")
	end

	local function getAllNPCs(targetName)
		local result = {}
		local function scan(folderName)
			local folder = workspace:FindFirstChild(folderName)
			if not folder then return end
			for _, npc in ipairs(folder:GetChildren()) do
				if npc:IsA("Model") and string.find(string.lower(npc.Name), string.lower(targetName), 1, true) then
					local hum = npc:FindFirstChild("Humanoid")
					local hrp = npc:FindFirstChild("HumanoidRootPart")
					if hum and hum.Health > 0 and hrp then
						table.insert(result, { npc = npc, hrp = hrp })
					end
				end
			end
		end
		scan("NPCs")
		scan("Enemies")
		return result
	end

	local function getClosestNPC(targetName)
		local rp = getHRP()
		if not rp then return nil end
		local closest, bestDist = nil, math.huge
		for _, d in ipairs(getAllNPCs(targetName)) do
			local dist = (rp.Position - d.hrp.Position).Magnitude
			if dist < bestDist then
				closest = d.npc
				bestDist = dist
			end
		end
		return closest
	end

	local function collectNPCPacket(targetName, centerPos, radius)
		local hrpList = {}
		local npcIDs = {}
		radius = radius or 24
		for _, d in ipairs(getAllNPCs(targetName)) do
			if d.hrp and (d.hrp.Position - centerPos).Magnitude <= radius then
				table.insert(hrpList, d.hrp)
				local id = getNPCID(d.npc)
				if id then table.insert(npcIDs, id) end
			end
		end
		return hrpList, npcIDs
	end

	local function getClosestNPCToPosition(targetName, centerPos, radius)
		local closest, bestDist = nil, math.huge
		radius = radius or 30
		for _, d in ipairs(getAllNPCs(targetName)) do
			local hum = d.npc and d.npc:FindFirstChild("Humanoid")
			if d.hrp and hum and hum.Health > 0 then
				local dist = (d.hrp.Position - centerPos).Magnitude
				if dist <= radius and dist < bestDist then
					closest = d.npc
					bestDist = dist
				end
			end
		end
		return closest
	end

	local AIR_HOLD_BV_NAME = "KT_AirHoldBV"

	local AIR_HOLD_BP_NAME = "KT_AirHoldBP"

	local function enableAirHold(rp, targetPos)
		if not rp then return end
		targetPos = targetPos or rp.Position
		local bv = rp:FindFirstChild(AIR_HOLD_BV_NAME)
		if not bv then
			bv = Instance.new("BodyVelocity")
			bv.Name = AIR_HOLD_BV_NAME
			bv.Parent = rp
		end
		bv.MaxForce = Vector3.new(1e9, 1e9, 1e9)
		bv.P = 1e7
		bv.Velocity = Vector3.zero
		local bp = rp:FindFirstChild(AIR_HOLD_BP_NAME)
		if not bp then
			bp = Instance.new("BodyPosition")
			bp.Name = AIR_HOLD_BP_NAME
			bp.Parent = rp
		end
		bp.MaxForce = Vector3.new(1e9, 1e9, 1e9)
		bp.P = 1e7
		bp.D = 1000
		bp.Position = targetPos
	end

	local function disableAirHold()
		local rp = getHRP()
		if not rp then return end
		local bv = rp:FindFirstChild(AIR_HOLD_BV_NAME)
		if bv then bv:Destroy() end
		local bp = rp:FindFirstChild(AIR_HOLD_BP_NAME)
		if bp then bp:Destroy() end
	end

	local function hardLockRoot(rp, hum, cf)
		if not rp or not hum then return end
		enableAirHold(rp, cf.Position)
		hum.PlatformStand = false
		hum.Sit = false
		hum.AutoRotate = false
		hum:ChangeState(Enum.HumanoidStateType.Freefall)
		rp.CFrame = cf
		rp.AssemblyLinearVelocity = Vector3.zero
		rp.AssemblyAngularVelocity = Vector3.zero
		rp.Velocity = Vector3.zero
	end

	local function lockAbovePosition(pos, duration)
		if typeof(pos) ~= "Vector3" then return end
		local untilTime = tick() + (duration or 0.25)
		while tick() < untilTime do
			local rp = getHRP()
			local hum = getHumanoid()
			if not rp or not hum or hum.Health <= 0 then break end
			hardLockRoot(rp, hum, CFrame.new(pos))
			RunService.Heartbeat:Wait()
		end
	end

	-- Calcule la CFrame de combat pour les yetis : on reste centre au-dessus

	-- du yeti Ã  hauteur fixedY, sans rotation couchÃ©e.

	local function getYetiCombatCFrame(yetiHrp, fixedY, currentRp)
		if not yetiHrp then return nil end
		local dist = tonumber(H.YETI_HIT_DISTANCE) or 8.5
		local hoverY = fixedY or (yetiHrp.Position.Y + (tonumber(H.YETI_HOVER_HEIGHT) or 8.3))
		local pos
		if dist <= 0 then
			pos = Vector3.new(yetiHrp.Position.X, hoverY, yetiHrp.Position.Z)
		else
			local away
			if currentRp then
				away = Vector3.new(
					currentRp.Position.X - yetiHrp.Position.X,
					0,
					currentRp.Position.Z - yetiHrp.Position.Z
				)
			end
			if not away or away.Magnitude <= 0.05 then
				local a = math.rad(tonumber(H.YETI_HIT_ROTATION_Y) or 0)
				away = Vector3.new(math.sin(a), 0, math.cos(a))
			else
				away = away.Unit
			end
			pos = Vector3.new(
				yetiHrp.Position.X + away.X * dist,
				hoverY,
				yetiHrp.Position.Z + away.Z * dist
			)
		end
		local rotX = math.rad(tonumber(H.YETI_HIT_ROTATION_X) or 0)
		local rotY = math.rad(tonumber(H.YETI_HIT_ROTATION_Y) or 0)
		local rotZ = math.rad(tonumber(H.YETI_HIT_ROTATION_Z) or 0)
		return CFrame.new(pos) * CFrame.Angles(rotX, rotY, rotZ)
	end

	local function lockAboveNPC(npc, hoverHeight, duration, fixedY)
		hoverHeight = hoverHeight or 8.6
		local untilTime = tick() + (duration or 0.25)
		local isYeti = npc and npc.Name == "Yeti"
		while tick() < untilTime do
			local rp = getHRP()
			local humSelf = getHumanoid()
			local hrp = npc and npc:FindFirstChild("HumanoidRootPart")
			local hum = npc and npc:FindFirstChild("Humanoid")
			if not rp or not humSelf or humSelf.Health <= 0 or not hrp or not hum or hum.Health <= 0 then
				break
			end
			local y = fixedY or (hrp.Position.Y + hoverHeight)
			local cf
			if isYeti then
				cf = getYetiCombatCFrame(hrp, y, rp) or CFrame.new(hrp.Position.X, y, hrp.Position.Z)
			else
				cf = CFrame.new(hrp.Position.X, y, hrp.Position.Z)
			end
			hardLockRoot(rp, humSelf, cf)
			RunService.Heartbeat:Wait()
		end
	end

	local function doDamageCombo(targetName, centerPos, lockPos, radius)
		local rp = getHRP()
		if not rp then return end
		equipMelee()
		local hoverHeight = 8.6
		if lockPos and typeof(lockPos) == "Vector3" then
			hoverHeight = math.max(2, lockPos.Y - centerPos.Y)
		end
		for combo = 1, 5 do
			if not KC_ON() then break end -- [PRINCE HUB] بالأصل: KaitunFarm / Sea2Farm
			local followNpc = getClosestNPCToPosition(targetName, centerPos, radius or 30)
			local fixedCombatY = lockPos and lockPos.Y or (centerPos.Y + hoverHeight)
			local clusterCenterPos = centerPos
			if followNpc then
				lockAboveNPC(followNpc, hoverHeight, 0.08, fixedCombatY)
			elseif lockPos then
				lockAbovePosition(lockPos, 0.08)
			end
			pcall(function()
				local current = getHRP()
				local followHrp = followNpc and followNpc:FindFirstChild("HumanoidRootPart")
				local followHum = followNpc and followNpc:FindFirstChild("Humanoid")
				local clusterRadius = math.max(radius or 24, 36)
				if current and followHrp and followHum and followHum.Health > 0 then
					clusterCenterPos = followHrp.Position
					current.CFrame = CFrame.new(followHrp.Position.X, fixedCombatY, followHrp.Position.Z)
					current.AssemblyLinearVelocity = Vector3.zero
					current.AssemblyAngularVelocity = Vector3.zero
				elseif current and lockPos then
					current.CFrame = CFrame.new(lockPos)
					current.AssemblyLinearVelocity = Vector3.zero
					current.AssemblyAngularVelocity = Vector3.zero
				end
				local hrpList, npcIDs = collectNPCPacket(targetName, clusterCenterPos, clusterRadius)
				if #hrpList == 0 and followHrp then
					hrpList = { followHrp }
					local id = getNPCID(followNpc)
					if id then npcIDs = { id } end
				end
				if #hrpList == 0 then return end
				combatRegister:InvokeServer({
					[1] = "swingsfx", [2] = "Melee", [3] = combo,
					[4] = "Ground", [5] = false, [6] = CombatAnims[combo],
					[7] = 2, [8] = 1.5,
				})
				current = getHRP()
				followHrp = followNpc and followNpc:FindFirstChild("HumanoidRootPart")
				followHum = followNpc and followNpc:FindFirstChild("Humanoid")
				if current and followHrp and followHum and followHum.Health > 0 then
					clusterCenterPos = followHrp.Position
					current.CFrame = CFrame.new(followHrp.Position.X, fixedCombatY, followHrp.Position.Z)
					current.AssemblyLinearVelocity = Vector3.zero
					current.AssemblyAngularVelocity = Vector3.zero
				elseif current and lockPos then
					current.CFrame = CFrame.new(lockPos)
					current.AssemblyLinearVelocity = Vector3.zero
					current.AssemblyAngularVelocity = Vector3.zero
				end
				local packet = {
					[1] = {
						[1] = "damage", [2] = hrpList, [3] = "Melee",
						[4] = { combo, "Ground", "Melee" }, [5] = true,
						[6] = current and current.CFrame or CFrame.new(lockPos or centerPos),
						aircombo = "Ground",
					}
				}
				if #npcIDs > 0 then packet[1].NPCIDs = npcIDs end
				combatRegister:InvokeServer(unpack(packet))
			end)
			if followNpc then
				lockAboveNPC(followNpc, hoverHeight, 0.05, fixedCombatY)
			elseif lockPos then
				lockAbovePosition(lockPos, 0.05)
			else
				task.wait(0.21)
			end
		end
		local finalNpc = getClosestNPCToPosition(targetName, centerPos, radius or 30)
		if finalNpc then
			local fixedFinalY = lockPos and lockPos.Y or (centerPos.Y + hoverHeight)
			lockAboveNPC(finalNpc, hoverHeight, 1, fixedFinalY)
		elseif lockPos then
			lockAbovePosition(lockPos, 1)
		else
			task.wait(1)
		end
	end

	local function hitSingleNPC(npc, hoverHeight)
		local hrp = npc and npc:FindFirstChild("HumanoidRootPart")
		local rp = getHRP()
		if not hrp or not rp then return end
		hoverHeight = hoverHeight or 8.6
		local fixedCombatY = hrp.Position.Y + hoverHeight
		lockAboveNPC(npc, hoverHeight, 0.12, fixedCombatY)
		local id = getNPCID(npc)
		pcall(function()
			local current = getHRP()
			local liveHrp = npc and npc:FindFirstChild("HumanoidRootPart")
			local liveHum = npc and npc:FindFirstChild("Humanoid")
			local packetCenter = liveHrp and liveHrp.Position or hrp.Position
			if current and liveHrp and liveHum and liveHum.Health > 0 then
				current.CFrame = CFrame.new(liveHrp.Position.X, fixedCombatY, liveHrp.Position.Z)
				current.AssemblyLinearVelocity = Vector3.zero
				current.AssemblyAngularVelocity = Vector3.zero
			end
			combatRegister:InvokeServer({
				[1] = "swingsfx", [2] = "Melee", [3] = 1,
				[4] = "Ground", [5] = false, [6] = CombatAnims[1],
				[7] = 2, [8] = 1.5,
			})
			current = getHRP()
			liveHrp = npc and npc:FindFirstChild("HumanoidRootPart")
			liveHum = npc and npc:FindFirstChild("Humanoid")
			packetCenter = liveHrp and liveHrp.Position or packetCenter
			if current and liveHrp and liveHum and liveHum.Health > 0 then
				current.CFrame = CFrame.new(liveHrp.Position.X, fixedCombatY, liveHrp.Position.Z)
				current.AssemblyLinearVelocity = Vector3.zero
				current.AssemblyAngularVelocity = Vector3.zero
			end
			local hrpList, npcIDs = collectNPCPacket(npc.Name, packetCenter, 22)
			if #hrpList == 0 then
				hrpList = { liveHrp or hrp }
				if id then npcIDs = { id } end
			end
			local packet = {
				[1] = {
					[1] = "damage", [2] = hrpList, [3] = "Melee",
					[4] = { 1, "Ground", "Melee" }, [5] = true,
					[6] = current and current.CFrame or CFrame.new(hrp.Position.X, fixedCombatY, hrp.Position.Z),
					aircombo = "Ground",
				}
			}
			if #npcIDs > 0 then packet[1].NPCIDs = npcIDs end
			combatRegister:InvokeServer(unpack(packet))
		end)
		lockAboveNPC(npc, hoverHeight, 0.45, fixedCombatY)
	end

	local FISHMAN_CAVE_PATH = {
		Vector3.new(8004.085, -2153.832, -17015.412),
		Vector3.new(8003.483, -2153.832, -17143.662),
		Vector3.new(7860.256, -2153.832, -17159.465),
		Vector3.new(7817.588, -2176.832, -17167.414),
		Vector3.new(7778.929, -2176.832, -17228.219),
		Vector3.new(7764.174, -2176.855, -17280.283),
		Vector3.new(7747.894, -2176.832, -17314.391),

	}

	local function cancelQuestIfDifferent(wantedQuest)
		wantedQuest = tostring(wantedQuest or "")
		local current = getQuest()
		if current == "" or current == wantedQuest then
			return false
		end
		notify("Quest", "Cancel old quest: " .. tostring(current) .. " -> " .. tostring(wantedQuest), 4)
		pcall(function()
			questEvent:InvokeServer({ [1] = "quit" })
		end)
		pcall(function()
			local args = { { "quit" } }
			questEvent:InvokeServer(unpack(args))
		end)
		task.wait(0.35)
		if getQuest() ~= "" and getQuest() ~= wantedQuest then
			local playerGui = LocalPlayer:FindFirstChild("PlayerGui")
			local quitBtn = playerGui
				and playerGui:FindFirstChild("Quest")
				and playerGui.Quest:FindFirstChild("Main")
				and playerGui.Quest.Main:FindFirstChild("Misc")
				and playerGui.Quest.Main.Misc:FindFirstChild("Quit")
			if quitBtn then
				pcall(function() quitBtn:Activate() end)
			end
		end
		task.wait(0.65)
		return true
	end

	local function takeQuest(questName, questPos, safeNoNoclip)
		if not questName or questName == "" then return end
		releaseMovementKeys()
		cancelQuestIfDifferent(questName)
		if getQuest() == questName then
			return
		end
		KF.teleport(questPos, safeNoNoclip == true, KC_ON) -- [PRINCE HUB] نفس DoSafeTeleport مال الكايتون
		task.wait(1)
		cancelQuestIfDifferent(questName)
		pcall(function()
			questEvent:InvokeServer({ [1] = "takequest", [2] = questName })
		end)
		task.wait(1)
	end

	local function getCrazyWolvesNear(pos, radius)
		local result = {}
		radius = radius or 22
		for _, d in ipairs(getAllNPCs(KC_TARGET)) do -- [PRINCE HUB] بالأصل getAllNPCs("Crazy Wolf")
			if d.hrp and (d.hrp.Position - pos).Magnitude <= radius then
				table.insert(result, d)
			end
		end
		return result
	end

	local function attackWolf(wolf)
		if not S2.canAttack then return end
		local hum = wolf and wolf:FindFirstChild("Humanoid")
		local hrp = wolf and wolf:FindFirstChild("HumanoidRootPart")
		if not hum or hum.Health <= 0 or not hrp then return end
		S2.canAttack = false
		equipMelee()
		local lockActive = true
		local lockConn = RunService.Heartbeat:Connect(function()
			if not lockActive then return end
			local liveHrp = wolf and wolf:FindFirstChild("HumanoidRootPart")
			local liveHum = wolf and wolf:FindFirstChild("Humanoid")
			local rp = getHRP()
			local selfHum = getHumanoid()
			if not liveHrp or not liveHum or liveHum.Health <= 0 or not rp or not selfHum or selfHum.Health <= 0 then
				return
			end
			setNoclip(true)
			local standPos = Vector3.new(liveHrp.Position.X, liveHrp.Position.Y + S2.upHeight, liveHrp.Position.Z)
			enableAirHold(rp, standPos)
			selfHum.AutoRotate = false
			selfHum.PlatformStand = false
			selfHum.Sit = false
			rp.CFrame = CFrame.new(standPos)
			rp.AssemblyLinearVelocity = Vector3.zero
			rp.AssemblyAngularVelocity = Vector3.zero
		end)
		for combo = 1, 5 do
			if not getgenv().Sea2Farm then break end
			hrp = wolf:FindFirstChild("HumanoidRootPart")
			hum = wolf:FindFirstChild("Humanoid")
			local rp = getHRP()
			if not hrp or not hum or hum.Health <= 0 or not rp then break end
			local npcPos = hrp.Position
			local standPos = Vector3.new(npcPos.X, npcPos.Y + S2.upHeight, npcPos.Z)
			enableAirHold(rp, standPos)
			rp.CFrame = CFrame.new(standPos)
			rp.AssemblyLinearVelocity = Vector3.zero
			rp.AssemblyAngularVelocity = Vector3.zero
			local hrpList = {}
			local npcIDs = {}
			for _, d in ipairs(getCrazyWolvesNear(npcPos, 22)) do
				table.insert(hrpList, d.hrp)
				local id = getNPCID(d.npc)
				if id then table.insert(npcIDs, id) end
			end
			if #hrpList == 0 then
				table.insert(hrpList, hrp)
				local id = getNPCID(wolf)
				if id then table.insert(npcIDs, id) end
			end
			pcall(function()
				local current = getHRP()
				local liveHrp = wolf and wolf:FindFirstChild("HumanoidRootPart")
				if current and liveHrp then
					local liveStandPos = Vector3.new(liveHrp.Position.X, liveHrp.Position.Y + S2.upHeight, liveHrp.Position.Z)
					enableAirHold(current, liveStandPos)
					current.CFrame = CFrame.new(liveStandPos)
					current.AssemblyLinearVelocity = Vector3.zero
					current.AssemblyAngularVelocity = Vector3.zero
				end
				combatRegister:InvokeServer({
					[1] = "swingsfx", [2] = "Melee", [3] = combo,
					[4] = "Ground", [5] = false, [6] = CombatAnims[combo],
					[7] = combo == 1 and 2 or 1.75, [8] = 1.5,
				})
				current = getHRP()
				liveHrp = wolf and wolf:FindFirstChild("HumanoidRootPart")
				if current and liveHrp then
					local liveStandPos = Vector3.new(liveHrp.Position.X, liveHrp.Position.Y + S2.upHeight, liveHrp.Position.Z)
					enableAirHold(current, liveStandPos)
					current.CFrame = CFrame.new(liveStandPos)
					current.AssemblyLinearVelocity = Vector3.zero
					current.AssemblyAngularVelocity = Vector3.zero
				end
				local packet = {
					[1] = {
						[1] = "damage", [2] = hrpList, [3] = "Melee",
						[4] = { combo, "Ground", "Melee" }, [5] = true,
						[6] = current and current.CFrame or rp.CFrame,
						aircombo = "Ground",
					}
				}
				if #npcIDs > 0 then packet[1].NPCIDs = npcIDs end
				combatRegister:InvokeServer(unpack(packet))
			end)
			task.wait(0.21)
		end
		lockActive = false
		if lockConn then lockConn:Disconnect() end
		local humEnd = getHumanoid()
		if humEnd then
			humEnd.AutoRotate = true
		end
		disableAirHold()
		task.wait(1)
		S2.canAttack = true
	end


	local KC = {
		equipMelee = equipMelee,
		getAllNPCs = getAllNPCs,
		getClosestNPC = getClosestNPC,
		getClosestNPCToPosition = getClosestNPCToPosition,
		enableAirHold = enableAirHold,
		disableAirHold = disableAirHold,
		lockAbovePosition = lockAbovePosition,
		lockAboveNPC = lockAboveNPC,
		hitSingleNPC = hitSingleNPC,
		getQuest = getQuest,
		getHRP = getHRP,
		FISHMAN_CAVE_PATH = FISHMAN_CAVE_PATH,
	}

	-- الفارم اللي يستخدم القتال هسه (حتى الـ combo يوقف أول ما ينطفي الفارم)
	function KC.setActive(isOn)
		KC_ON = isOn or function() return true end
	end

	function KC.doDamageCombo(targetName, centerPos, lockPos, radius)
		return doDamageCombo(targetName, centerPos, lockPos, radius)
	end

	function KC.takeQuest(questName, questPos)
		return takeQuest(questName, questPos)
	end

	function KC.attackWolf(npc, upHeight, targetName)
		S2.upHeight = tonumber(upHeight) or S2.upHeight
		KC_TARGET = targetName or (npc and npc.Name) or "Crazy Wolf"
		return attackWolf(npc)
	end

	-- لما الفارم يوقف: يشيل الـ air hold ويرجع الدوران
	function KC.stop()
		pcall(disableAirHold)
		local hum = getHumanoid()
		if hum then hum.AutoRotate = true end
		S2.canAttack = true
	end

	return KC
end)()

