local PN_savePending = false
local function PN_save()
	if PN_savePending then return end
	PN_savePending = true
	task.delay(0.5, function()
		PN_savePending = false
		pcall(function()
			if writefile then
				writefile(PN_SAVE_FILE, PN_Http:JSONEncode(PN_Saved))
			end
		end)
	end)
end

